-- Direct SQL Seed for Islamiyyat Quizzes

DO $$
DECLARE
  v_quiz_id_0 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أصول الدين - التوحيد صفاته وأدلتها', 'إسلاميات', 'أصول الدين الخمسة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_0;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'ما هي أصول الدين الخمسة عند الإمامية الاثني عشرية؟', '["التوحيد والعدل والنبوة والصلاة والحج","التوحيد والنبوة والجهاد والزكاة والصوم","التوحيد والنبوة والإمامة والعدل والمعاد","الإيمان والإسلام والإحسان والتقوى والجهاد"]'::jsonb, 2, 20, 0, 'multi', 'أصول الدين الخمسة عند الإمامية هي: التوحيد والعدل والنبوة والإمامة والمعاد، وهي الأركان العقدية التي يجب على المكلف معرفتها بالدليل.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'ما المقصود بالتوحيد كأول أصل من أصول الدين؟', '["الإقرار بأن الله واحد في ذاته وصفاته وأفعاله لا شريك له","الإقرار بوجود الله فقط دون وصفه بأي صفة","الإقرار بالصلاة والصوم لله وحده","اعتقاد أن الله لا يُرى ولا يُعلم"]'::jsonb, 0, 20, 1, 'multi', 'التوحيد يعني الاعتقاد بأن الله واحد أحد في ذاته وصفاته وأفعاله، لا شريك له ولا نظير، وهو مبحث مركزي في علم الكلام الإمامي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'كيف يُقسم علماء الكلام الإمامي صفات الله تعالى؟', '["إلى صفات كمالية وجمالية وجلالية","إلى صفات ذاتية وأفعالية فقط","إلى صفات واجبة وممكنة ومستحيلة","إلى صفات ثبوتية وصفات سلبية"]'::jsonb, 3, 20, 2, 'multi', 'يُقسم علماء الكلام الإمامي صفات الله إلى ثبوتية كمالية كالعلم والقدرة والحياة، وإلى سلبية تنزيهية كنفي الجسمية والمكان والشريك.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'ما الدليل العقلي الأبرز الذي يستخدمه المتكلمون الإماميون على وجود الله تعالى؟', '["دليل التجربة والحس","دليل الإمكان والوجوب","دليل الإجماع والنقل","دليل التواتر والسماع"]'::jsonb, 1, 20, 3, 'multi', 'دليل الإمكان والوجوب هو الأبرز، إذ يُقرر أن الممكن يحتاج إلى مرجّح وعلة، فلا بد من الانتهاء إلى واجب الوجود بالذات وهو الله تعالى.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'ما المعنى العقدي لوصف الله بأنه ''قديم'' في الفكر الكلامي الإمامي؟', '["أنه لا ابتداء لوجوده ولا أول له","أنه يتقدم على الأنبياء في المرتبة","أنه موجود منذ زمن طويل جداً","أنه أقدم المخلوقات وجوداً"]'::jsonb, 0, 20, 4, 'multi', 'القِدَم صفة سلبية تعني نفي السبق بالعدم، أي أن الله واجب الوجود لا ابتداء لوجوده، وهو مقابل الحدوث الثابت للمخلوقات.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'ما مضمون صفة ''العدل الإلهي'' التي يعدّها الإمامية أصلاً مستقلاً من أصول الدين؟', '["أن الله مُجبِر للعباد على أفعالهم","أن الله يساوي بين الناس في الرزق والعمر","أن الله يعاقب المؤمن والكافر بالتساوي","أن الله لا يظلم أحداً وأفعاله كلها حكمة وصواب"]'::jsonb, 3, 20, 5, 'multi', 'العدل الإلهي عند الإمامية يعني أن الله منزه عن الظلم والقبح، وأن أفعاله قائمة على الحكمة، وهو ما يستلزم إثبات حسن الأفعال وقبحها عقلاً.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'لماذا أفرد الإمامية ''العدل'' كأصل مستقل بينما يدخله أهل السنة ضمن التوحيد؟', '["لأن الجبر جائز عقلاً عند الإمامية","لأن الإمامية أثبتوا الحسن والقبح العقليين ونفوا الجبر وهو ما يميزهم عن الأشاعرة","لأن العدل الإلهي لا علاقة له بصفات الله","لأن العدل عندهم صفة مستقلة عن ذات الله"]'::jsonb, 1, 20, 6, 'multi', 'أفرد الإمامية العدل لأنهم يقولون بالتحسين والتقبيح العقليين ويثبتون حرية الإرادة، في مقابل الأشاعرة الذين ينفون ذلك، فصار العدل أصلاً مميزاً لهم.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'ما المقصود بالصفات السلبية لله تعالى في علم الكلام الإمامي؟', '["الصفات التي لا يجوز إطلاقها على الله أصلاً","الصفات التي تدل على سلب الرحمة عن العاصين","الصفات التي تنفي عن الله تعالى كل نقص وتشبيه بالمخلوقات","الصفات الدالة على غضب الله وانتقامه"]'::jsonb, 2, 20, 7, 'multi', 'الصفات السلبية هي صفات التنزيه التي تنفي عن الله ما لا يليق به كالجسمية والمكانية والحاجة والجهل والعجز، وهي جزء أساسي من منظومة التوحيد الإمامي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'هل يعتقد الإمامية أن معرفة أصول الدين تعبدية أم عقلية واجبة؟', '["كلاهما سواء ويجوز التقليد للعاجز","اختيارية يجوز فيها التقليد للعالم","تعبدية محضة تكفي فيها الشهادتان","عقلية واجبة لا يجوز فيها التقليد"]'::jsonb, 3, 20, 8, 'multi', 'يُجمع علماء الإمامية على أن معرفة أصول الدين واجبة بالدليل والنظر العقلي، ولا يجوز التقليد فيها، لأن الاعتقاد لا يُقبل إلا عن يقين واستدلال.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'ما الدليل النقلي القرآني الذي يُستشهد به على التوحيد في الفقه الكلامي الإمامي؟', '["قوله تعالى ''قل هو الله أحد'' في سورة الإخلاص","قوله تعالى ''إن الله على كل شيء قدير''","قوله تعالى ''وما خلقت الجن والإنس إلا ليعبدون''","قوله تعالى ''وهو الغفور الرحيم''"]'::jsonb, 0, 20, 9, 'multi', 'سورة الإخلاص وتحديداً قوله تعالى ''قل هو الله أحد'' من أبرز الأدلة القرآنية على التوحيد، وقد استشهد بها المتكلمون الإماميون على نفي التعدد والتركيب عن الذات الإلهية.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'أصول الدين الخمسة عند الإمامية تشمل الإمامة كأصل مستقل خلافاً لسائر المذاهب الإسلامية.', '["خطأ","صح"]'::jsonb, 1, 20, 10, 'boolean', 'صحيح، الإمامية أفردوا الإمامة أصلاً مستقلاً من أصول الدين الخمسة، بينما تعدّها سائر المذاهب مسألة فرعية فقهية لا أصلاً عقدياً.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_0, 'يرى علماء الكلام الإمامي أن دليل ''النظم والإتقان في الكون'' دليل على وجود الله وعلمه وقدرته.', '["صح","خطأ"]'::jsonb, 0, 20, 11, 'boolean', 'صحيح، دليل النظم أو العناية والاتقان في الكون يُستدل به على وجود الصانع العليم القادر، وهو من الأدلة المعتمدة في كتب الكلام الإمامي إلى جانب دليل الإمكان والوجوب.', 'أصول الدين الخمسة');
END $$;

DO $$
DECLARE
  v_quiz_id_1 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أصول الدين - العدل الإلهي وحكمة البلاء', 'إسلاميات', 'أصول الدين الخمسة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_1;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_1, 'ما هي أصول الدين الخمسة عند الإمامية الاثني عشرية؟', '["التوحيد والعدل والنبوة والإمامة والمعاد","التوحيد والنبوة والمعاد والجهاد والأمر بالمعروف","التوحيد والعدل والنبوة والولاية والزهد","الإيمان والعمل والتقوى والإمامة والمعاد"]'::jsonb, 0, 20, 0, 'multi', 'أصول الدين الخمسة عند الإمامية هي: التوحيد والعدل والنبوة والإمامة والمعاد، وهي المعروفة في علم الكلام الإمامي كما قررها العلامة الحلي وغيره.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_1, 'لماذا أضاف الإمامية ''العدل'' و''الإمامة'' إلى أصول الدين بشكل مستقل عن سائر المذاهب الإسلامية؟', '["لأن هذين الأصلين لم يذكرا في القرآن فأرادوا إبرازهما","لأن العدل يميزهم عن المعتزلة والإمامة تميزهم عن أهل السنة","لأن سائر المذاهب تنكر التوحيد والنبوة","لأن العدل صفة إلهية مستقلة تنفي التجبير وتثبت حرية الإرادة، والإمامة ركن ديني لا سياسي فحسب"]'::jsonb, 3, 20, 1, 'multi', 'يرى الإمامية أن إفراد العدل أصلاً مستقلاً يدفع عقيدة الجبر المنسوبة إلى الأشاعرة، وأن الإمامة ركن عقدي وليست مجرد مسألة سياسية، كما بينه الشيخ المفيد في أوائل المقالات.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_1, 'ما المقصود بـ''العدل'' في أصول الدين الإمامية؟', '["أن الله يُعذّب المطيعين ويثيب العاصين بالتساوي","أن الله يُساوي بين جميع الخلق في الرزق والحياة","أن أفعال الله تعالى كلها حسنة وحكيمة وأنه لا يفعل القبيح ولا يُخلّ بالواجب","أن القضاء الإلهي مجهول لا يُدرك بالعقل"]'::jsonb, 2, 20, 2, 'multi', 'العدل الإلهي في المنظومة الكلامية الإمامية يعني أن الله حكيم لا يفعل القبيح ولا يُخلّ بالواجب، وهو ما يوافق مذهب المعتزلة في التحسين والتقبيح العقليين، وقد شرحه الخواجة نصير الدين الطوسي في تجريد الاعتقاد.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_1, 'كيف يُفسّر علماء الإمامية وجود البلاء والمصائب في ضوء عقيدة العدل الإلهي؟', '["البلاء ليس له تفسير عقلي ويجب التسليم به دون تأمل","البلاء حكمته تكمين في الابتلاء والتمحيص والتكامل الروحي والتعويض الأخروي","البلاء نقمة لا تصيب إلا الكافرين","البلاء دليل على أن الله ظالم لبعض عباده"]'::jsonb, 1, 20, 3, 'multi', 'يرى المتكلمون الإمامية كالشيخ المفيد وابن ميثم البحراني أن البلاء يخدم غايات إلهية حكيمة كالتمحيص والتكامل والتعويض الأخروي، وهو لا يتعارض مع عدل الله لأن الله يُعوّض المُبتلى أضعافاً.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_1, 'ما الفرق بين موقف الإمامية والأشاعرة من مسألة الحسن والقبح العقليين وعلاقتها بالعدل الإلهي؟', '["الأشاعرة يقولون بالتحسين العقلي فقط في أفعال الإنسان لا في أفعال الله","الإمامية ينكرون دور العقل في إدراك الأحكام الشرعية","الإمامية والأشاعرة متفقون تماماً في هذه المسألة","الإمامية يقولون بالتحسين والتقبيح العقليين فالعقل يُدرك حسن العدل وقبح الظلم، أما الأشاعرة فيرون أن الحسن والقبح شرعيان فحسب"]'::jsonb, 3, 20, 4, 'multi', 'الإمامية وافقوا المعتزلة في القول بالتحسين والتقبيح العقليين، ومن ثَمَّ يرون أن الله لا يفعل الظلم لأن العقل يُدرك قبحه، بينما الأشاعرة يرون أن الحسن والقبح شرعيان، مما يعني أن الله لو عذّب المطيعين لم يكن ظالماً. بيّن هذا الفرق العلامة الحلي في كشف المراد.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_1, 'ما المكانة التي يحتلها أصل ''الإمامة'' في منظومة أصول الدين الإمامية؟', '["هي أصل عقدي جوهري لأن الإمام حافظ الدين ومرجع العصمة بعد النبي","هي أصل مستحدث أضافه المتكلمون المتأخرون دون سند من الروايات","هي أصل فقهي لا عقدي يتعلق بالخلافة السياسية فحسب","هي آخر الأصول وأقلها أهمية"]'::jsonb, 0, 20, 5, 'multi', 'يرى الإمامية أن الإمامة لطف إلهي واجب وأن الإمام المعصوم هو الحافظ للشريعة والمرجع الديني بعد النبي، وهو ما قرره الشيخ المفيد في الإرشاد والنصوص الكلامية الكبرى.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_1, 'ما الدليل الكلامي الذي يسوقه الإمامية على وجوب الإمامة استناداً إلى مبدأ اللطف الإلهي؟', '["الإمامة واجبة لأن القرآن نصّ عليها صراحةً باسم علي بن أبي طالب","اللطف الإلهي يقتضي أن لا يترك الله الخلق دون هادٍ معصوم يقربهم إلى الطاعة ويبعدهم عن المعصية","الإمامة واجبة لأن الناس طالبوا بها ديمقراطياً","اللطف الإلهي يعني أن كل إنسان يستطيع الوصول إلى الحق بعقله دون حاجة لإمام"]'::jsonb, 1, 20, 6, 'multi', 'يستند الإمامية في وجوب الإمامة إلى قاعدة اللطف الإلهي: إذا كان في فعل ما لطف بالعباد وتقريب لهم إلى الطاعة وجب على الله فعله، وتعيين الإمام المعصوم لطف واجب. قررها الشيخ الطوسي في الاقتصاد فيما يتعلق بالاعتقاد.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_1, 'ما الحكمة من ابتلاء الأنبياء والأولياء بالمصائب الشديدة رغم طاعتهم لله في نظر علماء الإمامية؟', '["لأن الله يعاقبهم على ذنوب خفية","لا توجد حكمة من ذلك وهو من المتشابهات التي لا تفسير لها","البلاء دليل على أن الأنبياء غير مُحبَّبين عند الله","لأن البلاء يرفع درجاتهم ويجعلهم قدوةً في الصبر وتكاملاً روحياً وتمحيصاً للأمة"]'::jsonb, 3, 20, 7, 'multi', 'تُقرر الروايات الإمامية ومنها ما في الكافي للكليني أن ''أشد الناس بلاءً الأنبياء ثم الأولياء ثم الأمثل فالأمثل''، والحكمة رفع الدرجات والتمحيص وكونهم نموذجاً للصبر والتسليم لله.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_1, 'ما الفرق بين ''البداء'' و''القضاء المبرم'' في العقيدة الإمامية وكيف يتصل ذلك بالعدل الإلهي؟', '["البداء يعني أن الله يجهل الغيب وينكشف له أمر لم يكن يعلمه","القضاء المبرم يعني الجبر المطلق وهو ما تؤمن به الإمامية","البداء يعني ظهور إرادة إلهية جديدة مرتبطة بأفعال العبد كالدعاء والصدقة، والقضاء المبرم ما لا يتغير، وكلاهما لا ينافي العلم الإلهي","البداء إنكار للمعاد وإثبات أن الحياة تنتهي بالموت"]'::jsonb, 2, 20, 8, 'multi', 'البداء في الاصطلاح الإمامي ليس جهلاً إلهياً بل هو إظهار ما أخفاه الله مشروطاً بأفعال العبد، فالدعاء والصدقة قد يُغيّران القدر المعلّق لا المبرم. وهذا يعزز العدل الإلهي إذ يربط المصير بالاختيار الإنساني، كما شرحه الكليني في أول الكافي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_1, 'كيف يُجيب المتكلمون الإمامية عن إشكالية تعرّض الأطفال والأبرياء للبلاء والألم مع القول بعدل الله؟', '["يستندون إلى التعويض الأخروي وكمال الحكمة الإلهية الخفية عن العقل المحدود مع إثبات ثواب عظيم للمُبتلى","يقولون إن بلاء الأطفال دليل على ذنب الأمة جمعاء لا الطفل","يقولون إن الله لا يُحاسَب على أفعاله فلا إشكال","يقولون إن الأطفال يُعذَّبون بذنوب آبائهم وهذا عدل"]'::jsonb, 0, 20, 9, 'multi', 'يُجيب المتكلمون الإمامية كالمحقق الطوسي وابن ميثم البحراني بأن الله يُعوّض المُبتلى البريء عوضاً عظيماً في الآخرة، وأن الحكمة الكاملة لأفعاله قد تخفى على العقل المحدود، وهذا لا يُناقض العدل بل يؤكد الرحمة والحكمة الإلهية.', 'أصول الدين الخمسة');
END $$;

DO $$
DECLARE
  v_quiz_id_2 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أصول الدين - النبوة والأنعام والعصمة', 'إسلاميات', 'أصول الدين الخمسة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_2;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما هي أصول الدين الخمسة عند الشيعة الإمامية الاثني عشرية؟', '["التوحيد والعدل والنبوة والزكاة والمعاد","التوحيد والنبوة والإمامة والعدل والمعاد","التوحيد والنبوة والجهاد والأمر بالمعروف والمعاد","التوحيد والنبوة والصلاة والصوم والمعاد"]'::jsonb, 1, 20, 0, 'multi', 'أصول الدين عند الإمامية خمسة: التوحيد والعدل والنبوة والإمامة والمعاد، وهي ما يجب على المكلف اعتقاده بالدليل العقلي والنقلي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما الأصل الذي يُميّز المذهب الإمامي عن سائر المذاهب الإسلامية في أصول الدين؟', '["العدل","التوحيد","الإمامة","المعاد"]'::jsonb, 2, 20, 1, 'multi', 'الإمامة هي الأصل الذي يميز الشيعة الإمامية عن غيرهم، إذ يعدّونها أصلاً من أصول الدين يجب الاعتقاد به بالدليل، وليست مجرد مسألة فرعية فقهية.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما معنى النبوة باعتبارها أصلاً من أصول الدين؟', '["الإيمان بأن النبي محمداً أفضل البشر دون الحاجة إلى دليل","الاعتقاد بأن النبوة موروثة في ذرية النبي فقط","الاعتقاد بأن الملائكة أبلغوا الرسالة بدلاً من البشر","الإيمان بأن الله أرسل رسلاً لهداية البشر وتبليغ الأحكام الإلهية"]'::jsonb, 3, 20, 2, 'multi', 'النبوة في أصول الدين تعني الاعتقاد بأن الله تعالى أرسل أنبياء ورسلاً معصومين لهداية البشر وتبليغ الشريعة الإلهية، وختمهم بالنبي محمد صلى الله عليه وآله.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما الدليل العقلي الرئيسي على ضرورة النبوة والإرسال؟', '["قاعدة اللطف الإلهي التي تستوجب إرسال الأنبياء لكمال الإنسان","حاجة الملوك إلى مشروعية دينية","اتفاق الأمم على وجود الأنبياء تاريخياً","النصوص القرآنية دون الحاجة إلى دليل عقلي"]'::jsonb, 0, 20, 3, 'multi', 'يستدل علماء الإمامية على ضرورة النبوة بقاعدة اللطف، إذ يقتضي الحكمة الإلهية إرسال الأنبياء لتكميل عقول البشر وهدايتهم إلى ما يصلحهم في الدنيا والآخرة.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما المقصود بعصمة الأنبياء في الفقه الجعفري؟', '["حماية الأنبياء من الأمراض الجسدية فقط","انعدام الإرادة الحرة عند الأنبياء","تنزّه الأنبياء عن الذنوب والخطأ في تبليغ الرسالة والأفعال والأقوال","عدم جواز نقد الأنبياء من قِبَل العلماء"]'::jsonb, 2, 20, 4, 'multi', 'العصمة عند الإمامية تعني أن الأنبياء والأئمة منزّهون عن الذنوب الصغيرة والكبيرة، وعن الخطأ في تلقي الوحي وتبليغه، وذلك بلطف إلهي لا يُخلّ بالاختيار.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'كم عدد الأنبياء المذكور في الروايات الإمامية عموماً؟', '["خمسة آلاف نبي","مئة وعشرون ألف نبي","ثلاثمئة وثلاثة عشر نبياً","أربعة وعشرون ألف نبي"]'::jsonb, 1, 20, 5, 'multi', 'وردت في الروايات الإمامية أن عدد الأنبياء مئة وعشرون ألف نبي، وأن عدد الرسل منهم ثلاثمئة وثلاثة عشر رسولاً، كما في روايات الكافي للكليني.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما العلاقة بين أصل العدل وأصل النبوة في المنظومة العقدية الإمامية؟', '["العدل الإلهي يقتضي إرسال الأنبياء لأن تكليف البشر دون بيان ظلم","العدل يلغي الحاجة إلى الأنبياء","العدل لا علاقة له بالنبوة بل يتعلق بالثواب والعقاب فقط","النبوة مقدمة على العدل في الأهمية العقدية"]'::jsonb, 0, 20, 6, 'multi', 'العدل الإلهي عند الإمامية يستلزم أن لا يكلف الله البشر دون إقامة الحجة عليهم بإرسال الأنبياء، فلا عقاب دون بيان، وهذا يربط أصل العدل بأصل النبوة ربطاً وثيقاً.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'من هو خاتم الأنبياء والمرسلين عند المسلمين عامة والإمامية خاصة؟', '["الإمام علي بن أبي طالب عليه السلام","النبي عيسى بن مريم عليه السلام","النبي إبراهيم الخليل عليه السلام","النبي محمد بن عبد الله صلى الله عليه وآله وسلم"]'::jsonb, 3, 20, 7, 'multi', 'النبي محمد بن عبد الله صلى الله عليه وآله وسلم هو خاتم الأنبياء والمرسلين بنص القرآن الكريم في سورة الأحزاب آية 40، ولا نبي بعده وشريعته خاتمة الشرائع.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'ما الفرق بين النبي والرسول في الاصطلاح الكلامي الإمامي؟', '["الرسول يُوحى إليه والنبي يرى المنامات فقط","لا فرق بينهما في الاصطلاح الإمامي","الرسول من أُمر بتبليغ شريعة جديدة والنبي يُنبَأ ولا يُلزم بالتبليغ العام","النبي أعلى مرتبة من الرسول دائماً"]'::jsonb, 2, 20, 8, 'multi', 'في الكلام الإمامي يُفرَّق بين النبي والرسول، فالرسول مكلَّف بتبليغ شريعة جديدة وإقامة الدين في المجتمع، أما النبي فيُنبَأ بالوحي وقد لا يكون مأموراً بالتبليغ العام على الرأي المشهور.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_2, 'لماذا اشترط علماء الإمامية العصمةَ في الأئمة قياساً على الأنبياء؟', '["لأن العصمة شرط اجتماعي للقيادة السياسية فقط","لأن الإمام يقوم مقام النبي في حفظ الشريعة وتبليغها بعد انقطاع الوحي","لأن الأئمة أنبياء يوحى إليهم بشريعة جديدة","لأن الإمام لا يحتاج إلى علم بالشريعة"]'::jsonb, 1, 20, 9, 'multi', 'استدل علماء الإمامية كالشيخ المفيد والشيخ الطوسي على وجوب عصمة الإمام بأنه خليفة النبي في حفظ الشريعة وبيانها، فلو جاز عليه الخطأ لم تُؤمَن الشريعة من التحريف، وهذا نفس الدليل المستعمل في عصمة الأنبياء.', 'أصول الدين الخمسة');
END $$;

DO $$
DECLARE
  v_quiz_id_3 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أصول الدين - الإمامة ومفهوم النص والتعيين', 'إسلاميات', 'أصول الدين الخمسة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_3;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما هي أصول الدين الخمسة عند الإمامية الاثني عشرية؟', '["التوحيد والنبوة والإمامة والعدل والمعاد","التوحيد والنبوة والجهاد والصلاة والزكاة","الإيمان والإسلام والإحسان والتوكل والتوبة","التوحيد والعدل والنبوة والولاية والصيام"]'::jsonb, 0, 20, 0, 'multi', 'أصول الدين عند الإمامية الاثني عشرية خمسة: التوحيد والعدل والنبوة والإمامة والمعاد، وهي المسائل الاعتقادية الكبرى التي يجب على المكلف أن يعتقد بها عن دليل ونظر.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'لماذا أدرج علماء الإمامية ''الإمامة'' ضمن أصول الدين لا ضمن الفروع؟', '["لأنها فريضة عبادية كالصلاة والصوم","لأنها متعلقة بالأحكام الفقهية الفرعية","لأنها مسألة اعتقادية يتوقف عليها الإيمان الكامل ولا يصح التقليد فيها","لأن القرآن نص عليها في سورة الفاتحة"]'::jsonb, 2, 20, 1, 'multi', 'الإمامية يعدون الإمامة أصلاً من أصول الدين لأنها قضية اعتقادية كبرى ترتبط بالولاية الإلهية وامتداد النبوة، ولا يجوز فيها التقليد بل يجب الاعتقاد بها عن دليل ونظر كما أوضح ذلك الشيخ المفيد في ''أوائل المقالات''.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما المقصود بـ''النص'' في مبحث الإمامة عند الإمامية؟', '["الإجماع الفقهي على اختيار الحاكم","تصريح النبي أو الإمام السابق بتعيين الإمام اللاحق بالاسم","الرأي العام للمسلمين في تعيين قائدهم","الآيات القرآنية المتعلقة بالصلاة والزكاة"]'::jsonb, 1, 20, 2, 'multi', 'النص في اصطلاح الإمامية يعني التصريح الصريح من النبي صلى الله عليه وآله أو من الإمام السابق بتعيين الإمام اللاحق باسمه وشخصه، كنص غدير خم على إمامة علي عليه السلام، وهو الركيزة الأساسية لمشروعية الإمامة.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما الآية القرآنية التي يستدل بها الإمامية على مبدأ التعيين الإلهي للإمام؟', '["''إنما وليكم الله ورسوله والذين آمنوا الذين يقيمون الصلاة ويؤتون الزكاة وهم راكعون''","''والذين جاهدوا فينا لنهدينهم سبلنا''","''قل هو الله أحد الله الصمد''","''وأقيموا الصلاة وآتوا الزكاة وأطيعوا الرسول''"]'::jsonb, 0, 20, 3, 'multi', 'آية الولاية في سورة المائدة (55) هي من أبرز الأدلة القرآنية التي يستشهد بها الإمامية على التعيين الإلهي، إذ يرون أنها نزلت في علي عليه السلام حين تصدق بخاتمه وهو راكع، وقد أوردها الطبرسي في ''مجمع البيان'' وغيره.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما الفرق الجوهري بين موقف الإمامية وموقف أهل السنة من مسألة تعيين الإمام؟', '["كلا الفريقين يتفقان على الشورى لكن يختلفان في التفاصيل","الإمامية يرون الانتخاب الشعبي، وأهل السنة يرون النص الإلهي","الإمامية يرون القرعة، وأهل السنة يرون الوراثة","الإمامية يرون التعيين الإلهي بالنص، وأهل السنة يرون الشورى أو الاختيار"]'::jsonb, 3, 20, 4, 'multi', 'الإمامية يؤكدون أن الإمامة منصب إلهي يتم بالنص والتعيين من الله ورسوله، بينما ذهب جمهور أهل السنة إلى أن الإمامة تثبت بالشورى والاختيار والبيعة، وهذا الخلاف موثق في كتب الكلام كـ''شرح المقاصد'' للتفتازاني و''تلخيص المحصل'' للطوسي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'كيف يُعرّف الشيخ المفيد الإمامة في كتابه ''أوائل المقالات''؟', '["مرتبة روحية خاصة لا تتعلق بالحكم والسياسة","رياسة عامة في أمور الدين والدنيا لشخص من البشر نيابةً عن النبي","منصب انتخابي يختاره العلماء بالإجماع","وظيفة دينية تقتصر على إمامة الصلاة وإصدار الفتاوى"]'::jsonb, 1, 20, 5, 'multi', 'عرّف الشيخ المفيد في ''أوائل المقالات'' الإمامة بأنها رياسة عامة في أمور الدين والدنيا لشخص من البشر نيابةً عن النبي صلى الله عليه وآله، وهو تعريف يُبرز شموليتها للبُعدين الديني والسياسي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما دلالة حديث الغدير ''من كنت مولاه فهذا علي مولاه'' في الاستدلال على الإمامة؟', '["يدل على النص الصريح بولاية علي وإمامته من بعد النبي","يدل على فضل علي دون تحديد منصب الإمامة له","يدل فقط على المحبة والمودة دون الإمارة والحكم","يدل على أفضلية علي في العبادة فحسب"]'::jsonb, 0, 20, 6, 'multi', 'يرى الإمامية أن حديث الغدير المروي في المصادر الإسلامية المختلفة نص جلي على إمامة علي عليه السلام، إذ أن لفظ ''مولى'' يعني الأولى بالتصرف والحاكم، وقد ناقش هذا الاستدلال بالتفصيل العلامة الحلي في ''نهج الحق وكشف الصدق''.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما علاقة مبدأ ''العصمة'' بمفهوم التعيين الإلهي للإمام عند الإمامية؟', '["التعيين الإلهي لا علاقة له بالعصمة بل يكفي العدالة","العصمة خاصة بالأنبياء وليست مطلوبة في الأئمة","العصمة شرط في الإمام لأن الله لا يُعيّن إلا من يأمن الخطأ والمعصية في تبليغ الدين","العصمة فضيلة مستحبة لكنها ليست شرطاً في التعيين"]'::jsonb, 2, 20, 7, 'multi', 'يرى الإمامية أن العصمة شرط جوهري في الإمام لأن الغرض من الإمامة هو حفظ الدين وصون الشريعة، فلو لم يكن الإمام معصوماً لاحتاج إلى إمام آخر وتسلسل الأمر. وقد أكد هذا الخواجة نصير الدين الطوسي في ''تجريد الاعتقاد''.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما الدليل العقلي الذي يسوقه الإمامية على وجوب الإمامة؟', '["الإمامة واجبة لأن النبي أوصى بها في وصيته الأخيرة فقط","قاعدة اللطف: الله يجب أن يُقرّب العباد إلى الطاعة بنصب إمام معصوم يهديهم","الإمامة واجبة من باب التقليد والاتباع للأعراف الإسلامية","الإمامة واجبة لأن الناس لا يستطيعون الاتفاق من تلقاء أنفسهم"]'::jsonb, 1, 20, 8, 'multi', 'يستدل الإمامية بقاعدة اللطف الإلهي على وجوب نصب الإمام، إذ اللطف الواجب على الله هو ما يُقرّب المكلف من الطاعة ويُبعده عن المعصية، ونصب الإمام المعصوم يحقق ذلك. وقد فصّل هذا الدليل الشيخ الطوسي في ''الاقتصاد فيما يتعلق بالاعتقاد''.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_3, 'ما موقف العلامة الحلي من كون الإمامة أصلاً من أصول الدين في كتابه ''باب الحادي عشر''؟', '["رأى أنها تثبت بالإجماع الفقهي لا بالنص","قال إنها من فروع الدين ويجوز التقليد فيها","أهملها ولم يعدّها من أصول الاعتقاد","أكد أن الإمامة ركن عقدي من أركان الإيمان يجب البحث فيها بالعقل لا بالتقليد"]'::jsonb, 3, 20, 9, 'multi', 'العلامة الحلي في كتابه ''باب الحادي عشر'' جعل الإمامة ركناً أساسياً من أركان العقيدة الإمامية، وأوضح أن البحث فيها واجب عقلي لا يجوز فيه التقليد، لأنها تتصل بضرورة وجود الحجة على الخلق في كل زمان.', 'أصول الدين الخمسة');
END $$;

DO $$
DECLARE
  v_quiz_id_4 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أصول الدين - المعاد والحساب والبرزخ', 'إسلاميات', 'أصول الدين الخمسة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_4;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما هو المعاد في العقيدة الإمامية الاثني عشرية؟', '["عودة الأرواح إلى الدنيا قبل يوم القيامة","فناء الروح مع الجسد عند الموت","انتقال الروح من جسد إلى آخر بعد الموت","بعث الإنسان بجسده وروحه للحساب والجزاء يوم القيامة"]'::jsonb, 3, 20, 0, 'multi', 'المعاد في العقيدة الإمامية هو إعادة الإنسان بجسده وروحه معاً يوم القيامة للحساب والجزاء، وهو من أصول الدين الخمسة التي لا يتم الإيمان إلا بها.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما هي أصول الدين الخمسة عند الشيعة الإمامية؟', '["التوحيد والنبوة والإمامة والعدل والجهاد","الصلاة والصيام والزكاة والحج والجهاد","التوحيد والعدل والنبوة والإمامة والمعاد","التوحيد والنبوة والمعاد والصلاة والزكاة"]'::jsonb, 2, 20, 1, 'multi', 'أصول الدين عند الشيعة الإمامية خمسة هي: التوحيد والعدل والنبوة والإمامة والمعاد، وهي الأسس العقدية التي يُبنى عليها الإيمان الكامل.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما المقصود بالبرزخ في العقيدة الإسلامية الشيعية؟', '["عالم ما بعد الحشر والحساب","عالم ما بين الموت والبعث يوم القيامة","المرحلة التي تسبق الخلق الأول للإنسان","مرحلة الصراط والميزان"]'::jsonb, 1, 20, 2, 'multi', 'البرزخ هو العالم الواسط بين الموت والبعث يوم القيامة، وقد أثبته القرآن الكريم بقوله تعالى ''ومن ورائهم برزخ إلى يوم يبعثون''، ويُعدّ مرحلة يلقى فيها الإنسان جزاءً أولياً على أعماله.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ماذا يعني مبدأ العدل الإلهي في أصول الدين الإمامية؟', '["أن الله منزّه عن الظلم وأفعاله كلها قائمة على الحكمة والعدل","أن الله يجازي الناس في الدنيا فقط","أن الله يساوي بين المؤمن والكافر في الثواب","أن العدل خاصية بشرية لا تنسب إلى الله"]'::jsonb, 0, 20, 3, 'multi', 'العدل الإلهي عند الإمامية يعني أن الله سبحانه منزّه عن كل ظلم وقبيح، وأن جميع أفعاله قائمة على الحكمة والعدل، وهذا يميّز المذهب الإمامي والمعتزلة عن الأشاعرة في هذه المسألة.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما الذي يميّز عقيدة الإمامية في المعاد عن بعض الفرق الأخرى؟', '["اعتقادها أن المعاد يكون في الدنيا لا في الآخرة","إيمانها بأن المعاد روحاني فقط دون الجسد","إنكارها للحساب والجزاء في الآخرة","إيمانها بالمعاد الجسماني والروحاني معاً"]'::jsonb, 3, 20, 4, 'multi', 'تعتقد الإمامية بالمعاد الجسماني والروحاني معاً، أي أن الإنسان يُبعث بجسده المادي وروحه يوم القيامة، وهذا ما يفترق به الإمامية عن من يقول بالمعاد الروحاني المحض.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما هو الميزان في عقيدة المعاد الإسلامية؟', '["الشفاعة التي يقدمها الأنبياء للمذنبين","كتاب تُسجّل فيه الأعمال","المقياس الذي تُوزن به أعمال العباد يوم القيامة","الصراط الممدود على النار"]'::jsonb, 2, 20, 5, 'multi', 'الميزان هو المقياس الإلهي الذي تُوزن به أعمال العباد يوم القيامة، وقد أشار إليه القرآن الكريم في قوله ''ونضع الموازين القسط ليوم القيامة''، وهو من مراحل الحساب الأخروي.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما المقصود بـ ''الصراط'' في عقيدة المعاد عند الإمامية؟', '["مرحلة السؤال في القبر","الجسر الممدود على جهنم الذي يعبر عليه الناس للوصول إلى الجنة","طريق الجنة في الدنيا","كتاب يُقرأ فيه سجل الأعمال"]'::jsonb, 1, 20, 6, 'multi', 'الصراط هو الجسر الممدود على جهنم الذي يجب على الناس عبوره للوصول إلى الجنة يوم القيامة، وهو من الحقائق الأخروية الثابتة في عقيدة الإمامية استناداً إلى الروايات والآيات القرآنية.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما حكم الشفاعة في عقيدة الإمامية الاثني عشرية؟', '["منكرة كلياً لأنها تنافي العدل الإلهي","خاصة بالأنبياء فقط دون الأئمة والصالحين","تشمل جميع الناس مؤمنين وكافرين بلا استثناء","ثابتة بإذن الله للأنبياء والأئمة والشهداء لأهل الإيمان"]'::jsonb, 3, 20, 7, 'multi', 'الشفاعة ثابتة في عقيدة الإمامية بإذن الله تعالى، وتشمل الأنبياء والأئمة والشهداء والعلماء، وهي خاصة بأهل الإيمان الذين ارتكبوا الذنوب، استناداً لقوله تعالى ''ولا يشفعون إلا لمن ارتضى''.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما الذي تعتقده الإمامية بشأن عذاب القبر في مرحلة البرزخ؟', '["يعتبرونه من الأمور الموهومة التي لا أساس لها","يثبتونه للكافرين فقط دون المؤمنين المذنبين","يثبتونه استناداً للأحاديث والآيات وهو جزء من حياة البرزخ","ينكرونه كلياً لأنه لم يرد في القرآن"]'::jsonb, 2, 20, 8, 'multi', 'تثبت الإمامية عذاب القبر ونعيمه استناداً للآيات القرآنية كقوله تعالى في آل فرعون ''النار يُعرضون عليها غدواً وعشياً'' وللأحاديث المروية عن أهل البيت عليهم السلام، وهو من حقائق عالم البرزخ.', 'أصول الدين الخمسة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_4, 'ما الفرق بين الحشر والبعث في المصطلح العقدي الإمامي؟', '["البعث هو إعادة الحياة للأموات والحشر هو جمعهم للحساب في يوم القيامة","هما مصطلحان مترادفان تماماً لا فرق بينهما","البعث يكون روحانياً والحشر جسمانياً","الحشر يخص المؤمنين فقط والبعث يشمل الجميع"]'::jsonb, 0, 20, 9, 'multi', 'البعث هو إعادة الحياة للأموات بجسدهم وروحهم يوم القيامة، أما الحشر فهو جمع الخلائق في موقف واحد للحساب والجزاء، وإن كان بعض العلماء يستخدمهما بمعنى متقارب إلا أن ثمة فرقاً دقيقاً بينهما في توظيفهما العقدي.', 'أصول الدين الخمسة');
END $$;

DO $$
DECLARE
  v_quiz_id_5 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('مفهوم الإمامة وأدلة العصمة الشرعية', 'إسلاميات', 'الإمامة والعصمة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_5;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما التعريف الاصطلاحي للإمامة في الفقه الجعفري؟', '["مرتبة شرفية تُمنح لآل البيت دون صلاحيات تشريعية","وظيفة دينية تقتصر على إقامة الصلاة وتعليم الشريعة","منصب سياسي يُنتخب فيه الأفضل من المسلمين","رئاسة عامة في أمور الدين والدنيا خلافةً عن النبي"]'::jsonb, 3, 20, 0, 'multi', 'عرّف علماء الإمامية الإمامة بأنها رئاسة عامة إلهية في أمور الدين والدنيا خلافةً عن النبي صلى الله عليه وآله، وهذا ما أكده الشيخ المفيد في أوائل المقالات والعلامة الحلي في كشف المراد.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما الدليل القرآني الرئيسي الذي يستند إليه الإمامية لإثبات عصمة الأئمة؟', '["آية التطهير: ''إنما يريد الله ليذهب عنكم الرجس أهل البيت''","آية الولاية: ''النبي أولى بالمؤمنين من أنفسهم''","آية الأمانة: ''إن الله يأمركم أن تؤدوا الأمانات إلى أهلها''","آية الشورى: ''وأمرهم شورى بينهم''"]'::jsonb, 0, 20, 1, 'multi', 'يستدل الإمامية بآية التطهير (الأحزاب:33) على عصمة أهل البيت، إذ إن نفي الرجس المطلق يستلزم العصمة عن الذنب والخطأ، وقد وثّق ذلك الشيخ الطوسي في التبيان والطبرسي في مجمع البيان.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما الحديث النبوي الذي يعدّه الإمامية دليلاً قاطعاً على إمامة علي بن أبي طالب بعد النبي مباشرةً؟', '["حديث الثقلين: ''إني تارك فيكم الثقلين''","حديث المنزلة: ''أنت مني بمنزلة هارون من موسى''","حديث الغدير: ''من كنت مولاه فهذا علي مولاه''","حديث السفينة: ''مثل أهل بيتي فيكم كمثل سفينة نوح''"]'::jsonb, 2, 20, 2, 'multi', 'حديث الغدير المروي في صحيح مسلم ومسند أحمد وغيرهما هو الأبرز لدى الإمامية في إثبات الإمامة المباشرة لعلي، وقد استدل به الشيخ المفيد والسيد المرتضى استدلالاً مفصلاً.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'كيف يُفسّر علماء الإمامية العقلي لضرورة عصمة الإمام؟', '["لأن الشعب لا يثق إلا بمن لا يُخطئ في أمور الدنيا","لأن غير المعصوم يحتاج إلى مُصحِّح آخر فيلزم التسلسل","لأن الإمام مفوَّض بالتشريع ولا حاجة للعصمة في التطبيق","لأن الإمام يجب أن يكون من قريش فحسب"]'::jsonb, 1, 20, 3, 'multi', 'يقرر الخواجه نصير الدين الطوسي في تجريد الاعتقاد أن الإمام لو لم يكن معصوماً لاحتاج إلى إمام معصوم يُصوِّبه فيلزم التسلسل أو الدور، وهو برهان عقلي لإثبات ضرورة العصمة.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما مفهوم العصمة في الاصطلاح الكلامي الإمامي؟', '["إجبار رباني يسلب المعصوم الإرادة والاختيار","مجرد تنزيه اجتماعي يُعطي المعصوم سمعة حسنة","صفة وراثية تنتقل عبر الدم من النبي إلى أبنائه فقط","لطف إلهي يجعل المعصوم قادراً على ترك المعصية اختياراً مع القدرة عليها"]'::jsonb, 3, 20, 4, 'multi', 'عرّف الشيخ المفيد في تصحيح الاعتقاد والعلامة الحلي في كشف المراد العصمة بأنها لطف من الله يجعل صاحبه داعياً إلى ترك القبيح مع بقاء القدرة عليه، فلا تنافي الاختيار.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما عدد الأئمة الذين يعتقد الإمامية الاثنا عشرية بإمامتهم؟', '["اثنا عشر إماماً من علي بن أبي طالب إلى المهدي المنتظر","سبعة أئمة ينتهون بإسماعيل بن جعفر","أحد عشر إماماً وتنتهي الإمامة بالحسن العسكري","عشرة أئمة يبدأون بالحسن ويختمون بالرضا"]'::jsonb, 0, 20, 5, 'multi', 'تعتقد الإمامية الاثنا عشرية بإمامة اثني عشر إماماً تبدأ بعلي بن أبي طالب وتنتهي بمحمد بن الحسن المهدي المنتظر، وهو ما أجمع عليه علماؤهم كالشيخ الصدوق في كمال الدين.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما دلالة حديث الثقلين على إمامة أهل البيت وعصمتهم؟', '["دلالته مقتصرة على وجوب محبة آل البيت دون اتباعهم","الأمر بالتمسك بهم مع القرآن دليل على انتفاء الخطأ عنهم","الحديث يدل على فضلهم الأخلاقي لا على إمامتهم السياسية","الحديث موضوع ولا يُحتج به في مسائل الإمامة"]'::jsonb, 1, 20, 6, 'multi', 'يستدل علماء الإمامية كالسيد الخوئي في البيان بأن الأمر بالتمسك بأهل البيت قرين القرآن يقتضي أن يكون قولهم حجة مطلقة، وهذا لا يتم إلا مع عصمتهم من الخطأ.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما الفرق الجوهري بين مفهوم الإمامة عند الإمامية ومفهوم الخلافة عند أهل السنة؟', '["الإمامة تقتصر على الجانب الديني، والخلافة على الجانب السياسي","الإمامة وراثية من الأب للابن دون اشتراط العصمة","لا فرق جوهري بينهما إلا في التسمية والشكل","الإمامة منصب إلهي بالنص والعصمة، والخلافة بشرية بالاختيار والشورى"]'::jsonb, 3, 20, 7, 'multi', 'يرى الإمامية أن الإمامة منصب إلهي يُعيَّن فيه الإمام بنص من الله عبر النبي ويشترط فيه العصمة، بينما يرى أهل السنة أن الخلافة تثبت بالاختيار والشورى دون اشتراط العصمة، وهو ما أوضحه السيد المرتضى في الشافي.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما الموقف الإمامي من عصمة الإمام في مجال تلقي الوحي والتشريع؟', '["الأئمة مفوَّضون بالتشريع ويجوز لهم تعديل الأحكام القرآنية","الأئمة يتلقون وحياً تشريعياً مستقلاً يضاف إلى القرآن","الأئمة لا يتلقون وحياً تشريعياً جديداً لكنهم معصومون في بيان ما ورثوه من علم النبي","الأئمة لا يختلفون عن بقية العلماء إلا في النسب الشريف"]'::jsonb, 2, 20, 8, 'multi', 'يُقرر الشيخ الصدوق والشيخ المفيد أن الأئمة لا يتلقون وحياً تشريعياً جديداً بعد النبي، بل يحملون علمه ويُبيّنونه بعصمة تامة، وهذا يميزهم عن النبوة مع إثبات حجية قولهم.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_5, 'ما المقصود بمبدأ ''اللطف'' في علم الكلام الإمامي وصلته بوجوب نصب الإمام؟', '["حق للعباد يُطالبون به دون أن يكون واجباً على الله","وجوب على الله إيجاد ما يُقرّب العباد إلى الطاعة ويُبعدهم عن المعصية","فضل إضافي من الله لا يترتب على تركه أي محذور عقلي","مبدأ صوفي يتعلق بالمحبة الإلهية لا بالتكاليف الشرعية"]'::jsonb, 1, 20, 9, 'multi', 'يُعرّف السيد المرتضى في الذخيرة والشيخ الطوسي في الاقتصاد اللطفَ بأنه ما يكون المكلف معه أقرب إلى فعل الطاعة وأبعد عن المعصية، ويستنتجون وجوب نصب الإمام المعصوم تحقيقاً لهذا اللطف الإلهي.', 'الإمامة والعصمة');
END $$;

DO $$
DECLARE
  v_quiz_id_6 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أدلة إمامة الأئمة الاثني عشر (ع) نصاً وتاريخاً', 'إسلاميات', 'الإمامة والعصمة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_6;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما المقصود بمبدأ العصمة في الفكر الإمامي الاثني عشري؟', '["أن الإمام يعصم نفسه بالاجتهاد الشخصي","أن العصمة تعني الاستحالة الطبيعية للذنب","أن الإمام يخطئ لكن يتوب فوراً","أن الإمام محفوظ من الخطأ والمعصية بتوفيق إلهي خاص"]'::jsonb, 3, 20, 0, 'multi', 'العصمة عند الإمامية هي لطف إلهي يمنح الإمام القدرة على اجتناب الذنوب والأخطاء في التبليغ والعمل، وهي ليست قسراً بل اختياراً مؤيداً بنعمة الله، كما أكده الشيخ المفيد في كتاب ''أوائل المقالات''.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'أي آية قرآنية استدل بها علماء الإمامية على اشتراط العصمة في الإمام استناداً إلى عدم نيل العهد الظالمين؟', '["آية ''أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم''","آية ''لا ينال عهدي الظالمين''","آية ''إنما وليكم الله ورسوله''","آية ''اليوم أكملت لكم دينكم''"]'::jsonb, 1, 20, 1, 'multi', 'استدل علماء الإمامية كالشيخ الطوسي والعلامة الحلي بقوله تعالى في سورة البقرة آية 124: ''لا ينال عهدي الظالمين''، ليثبتوا أن الإمامة لا تجوز لمن ارتكب الظلم ولو لحظة، فتنحصر في المعصوم.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما الحديث النبوي الذي استشهد به الإماميون على تحديد عدد الأئمة باثني عشر إماماً؟', '["حديث الثقلين المروي عن جابر","حديث ''من مات ولم يعرف إمام زمانه مات ميتة جاهلية''","حديث ''لا يزال الدين قائماً حتى تقوم الساعة ويكون اثنا عشر خليفة كلهم من قريش''","حديث ''أنا مدينة العلم وعلي بابها''"]'::jsonb, 2, 20, 2, 'multi', 'حديث الاثني عشر خليفة أو أميراً مروي في صحيح البخاري ومسلم وغيرهما عن جابر بن سمرة، وقد وظّفه علماء الإمامية كابن بابويه القمي في ''كمال الدين'' دليلاً على انحصار الخلافة الحقة في الأئمة الاثني عشر.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما العلاقة بين العصمة والنص في منظومة الإمامة الجعفرية؟', '["النص الإلهي أو النبوي على الشخص المعصوم هو الطريق الوحيد لمعرفة الإمام","العصمة والنص مستقلان ولا يرتبطان ببعضهما","العصمة تغني عن النص لأن المعصوم يُعرف بأعماله","النص وحده يكفي لإثبات الإمامة دون الحاجة إلى العصمة"]'::jsonb, 0, 20, 3, 'multi', 'يرى المتكلمون الإماميون كالشيخ المفيد والخواجة نصير الدين الطوسي في ''تجريد الاعتقاد'' أن العقل يُثبت ضرورة العصمة، لكن تعيين الشخص المعصوم لا يمكن إلا بنص من الله أو رسوله أو الإمام السابق.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما حديث الغدير وأهميته في إثبات إمامة أمير المؤمنين علي (ع) نصاً؟', '["حديث خطب به أبو بكر بعد وفاة النبي","حديث روي عن علي نفسه يُعلن فيه إمامته","حديث قاله النبي في مسجد المدينة قبيل وفاته","حديث أعلن فيه النبي ولاية علي في غدير خم عند عودته من حجة الوداع"]'::jsonb, 3, 20, 4, 'multi', 'في الثامن عشر من ذي الحجة سنة عشر للهجرة، أعلن النبي (ص) في غدير خم قائلاً: ''من كنت مولاه فهذا علي مولاه''. وقد وثّق العلامة الأميني هذا الحديث في موسوعة ''الغدير'' من طرق أهل السنة والشيعة، وعدّه الإماميون النص الجلي على إمامة علي (ع).', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما الدليل العقلي الذي ساقه الخواجة نصير الدين الطوسي على وجوب عصمة الإمام في ''تجريد الاعتقاد''؟', '["أن العصمة دليل حسي يُعرف بالمعجزات فقط","أن الإمام غير المعصوم يحتاج إلى إمام آخر يصحح أخطاءه فيتسلسل الأمر إلى ما لا نهاية","أن الإمام يُنتخب بالشورى فلا حاجة للعصمة","أن الإمام المعصوم يتميز بعلامات ظاهرة لا تخطئها العيون"]'::jsonb, 1, 20, 5, 'multi', 'استخدم الخواجة نصير الدين الطوسي في ''تجريد الاعتقاد'' حجة التسلسل: إذا كان الإمام غير معصوم احتاج إلى إمام يقوم بتصحيحه، وذاك إن لم يكن معصوماً احتاج لآخر، وهكذا إلى ما لا نهاية، فوجب أن ينتهي الأمر إلى معصوم.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما النص الوارد في حديث الثقلين الدال على الحجية الدائمة لأهل البيت (ع)؟', '["''تركت فيكم ما إن تمسكتم به لن تضلوا: كتاب الله وعترتي أهل بيتي''","''أهل بيتي كسفينة نوح من ركبها نجا''","''كتاب الله وسنتي ولن يفترقا''","''علي مع الحق والحق مع علي''"]'::jsonb, 0, 20, 6, 'multi', 'حديث الثقلين المروي بطرق متعددة في مصادر الفريقين، ومنها مسند أحمد وسنن الترمذي، ينص على أن النبي (ص) خلّف الكتاب والعترة ولن يفترقا حتى يردا عليه الحوض، وقد استدل به الإماميون على استمرار الحجية في أئمة أهل البيت (ع).', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'لماذا يرى علماء الإمامية أن الإمامة من أصول الدين لا من فروعه؟', '["لأنها تثبت بالشورى والاتفاق العام","لأن الفقهاء قرروا ذلك باجتهادهم الجماعي","لأنها منصب إلهي يرتبط بحفظ الدين وهداية البشر استمراراً للنبوة","لأنها تتعلق بالعبادات العملية كالصلاة والصوم"]'::jsonb, 2, 20, 7, 'multi', 'يذهب علماء الإمامية كالشيخ المفيد في ''الإرشاد'' والعلامة الحلي في ''باب الحادي عشر'' إلى أن الإمامة رئاسة إلهية عامة لحفظ الشريعة وهداية الأمة، وهي امتداد لوظيفة النبوة، فلا تثبت بالاختيار البشري بل بالنص الإلهي.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'أي مؤلَّف كلامي جمع أدلة إمامة الأئمة الاثني عشر (ع) نصاً على نصاً من المصادر الروائية؟', '["''نهج البلاغة'' لجمع خطب الإمام علي (ع)","''الكافي'' للكليني في باب الحجة","''الشافي في الإمامة'' للسيد المرتضى","''تهذيب الأحكام'' للشيخ الطوسي"]'::jsonb, 1, 20, 8, 'multi', 'خصص الشيخ الكليني في كتابه ''الكافي'' أبواباً مفصّلة تحت عنوان ''كتاب الحجة'' تجمع الروايات المسندة على النص على كل إمام من أئمة أهل البيت (ع) بالاسم، من أمير المؤمنين حتى الإمام المهدي (عج).', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_6, 'ما موقف الإمام جعفر الصادق (ع) من مسألة تحديد الإمام بالنص كما رواه الكليني في ''الكافي''؟', '["قال إن الإمامة تثبت للأفضل علماً بين أبناء الإمام","أكد أن الأمة تختار الإمام بشرط أن يكون هاشمياً","أجاز اختيار الإمام بإجماع العلماء إن غاب النص","قرر أن الإمامة لا تنتقل إلا بنص الإمام السابق على خلفه"]'::jsonb, 3, 20, 9, 'multi', 'روى الكليني في ''الكافي'' عن الإمام الصادق (ع) أحاديث صريحة تبيّن أن الإمامة عهد من الله ينتقل بنص الإمام الحي على من يخلفه، وأن الأمة لا حق لها في الاختيار، وهو ما شكّل ركيزة في الفكر الإمامي الاثني عشري.', 'الإمامة والعصمة');
END $$;

DO $$
DECLARE
  v_quiz_id_7 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('العصمة وشروط الإمام وصفاته الإلهية', 'إسلاميات', 'الإمامة والعصمة', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_7;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما المقصود بعصمة الإمام في العقيدة الإمامية الاثني عشرية؟', '["قدرة الإمام على الدفاع عن نفسه في المعارك","صون الإمام من الخطأ والذنب في تبليغ الأحكام وتطبيقها","تمتع الإمام بالسلطة السياسية المطلقة","علم الإمام الواسع بعلوم الدنيا فحسب"]'::jsonb, 1, 20, 0, 'multi', 'العصمة عند الإمامية تعني صون الإمام من الخطأ والنسيان والذنب في جميع جوانب التبليغ والتطبيق والسلوك، وهي شرط جوهري في الإمام كما قرره الشيخ المفيد والعلامة الحلي.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'من أي مصدر يستمد الإمام عصمته وفق العقيدة الإمامية؟', '["من فضل إلهي خاص يمنحه الله تعالى للإمام","من تزكية الأمة له بالانتخاب والبيعة","من إجماع العلماء والفقهاء على صلاحه","من خلال الاجتهاد الفردي الطويل"]'::jsonb, 0, 20, 1, 'multi', 'العصمة موهبة إلهية يختص الله بها من يشاء من عباده، فالإمام لا يكتسبها بجهده بل يُودعها الله فيه بلطفه، كما صرح بذلك المحقق الطوسي في تجريد الاعتقاد.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما الشرط الذي يميز الإمام الاثني عشري عن سائر العلماء والفقهاء وفق العلامة الحلي؟', '["الحصول على أعلى درجات الاجتهاد الفقهي","النسب القرشي من بني أمية","الشجاعة في الحرب والقيادة العسكرية","العصمة من الخطأ والذنب والنسيان"]'::jsonb, 3, 20, 2, 'multi', 'صرّح العلامة الحلي في كتاب ''كشف المراد'' بأن العصمة شرط لازم في الإمام يميزه عن غيره، إذ لا يصح أن يكون قائد الأمة الدينية والسياسي معرضاً للخطأ والذنب.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما موقف الإمامية من إمامة من ليس بمعصوم؟', '["تجوز إمامته في الشؤون الدنيوية دون الدينية","لا تصح إمامته مطلقاً لأن العصمة شرط أساسي","يمكن قبول إمامته بشرط الإجماع","تصح إمامته إذا كان عادلاً وعالماً"]'::jsonb, 1, 20, 3, 'multi', 'يرى الإمامية أن الإمامة الحقة لا تنعقد لغير المعصوم، لأن الغرض من الإمامة هو الحفاظ على الشريعة من التحريف والخطأ، وهذا لا يتحقق إلا بالمعصوم، كما قرره الشيخ المفيد في ''الإرشاد''.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما معنى قول الإمامية بأن الإمام يعلم متى يموت ولا يموت إلا باختياره؟', '["أن الإمام يملك القدرة على تحديد أجله الطبيعي بإرادته","أن الإمام لا يخضع لقوانين الطبيعة البشرية","أن الإمام مُطلع بعلم إلهي على أجله فيكون موته شهادة واعية","أن الإمام لا يمرض ولا يتألم"]'::jsonb, 2, 20, 4, 'multi', 'تعني هذه العقيدة أن الإمام يُفاض عليه علم بأجله فيستقبل الشهادة باختيار واعٍ، لا أن يتحكم في القدر المحتوم، وهو ما أشار إليه الكليني في ''الكافي'' في باب أن الأئمة يعلمون متى يموتون.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'كيف يستدل الإمامية على العصمة من الآية الكريمة ''لا ينال عهدي الظالمين''؟', '["الآية تنفي الإمامة عمن ارتكب ظلماً ولو مرة في حياته فوجب العصمة","الظالم هنا يقصد به الكافر فقط فلا يُعيَّن إماماً","الظلم في الآية محصور بالظلم السياسي دون الذنوب الأخرى","الآية خاصة بإمامة بني إسرائيل وليست حجة في الإسلام"]'::jsonb, 0, 20, 5, 'multi', 'استدل العلامة الحلي وغيره بأن الآية تنفي الإمامة عن الظالم، وكل من أذنب ولو ذنباً واحداً فقد ظلم نفسه، فلا يصح أن يكون إماماً، وهذا يقتضي أن يكون الإمام معصوماً طوال حياته.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما العلم الذي يتمتع به الإمام المعصوم وفق روايات الكافي للكليني؟', '["علم القرآن الكريم حفظاً وتفسيراً فحسب","علم ما كان وما يكون وما هو كائن حتى تقوم الساعة","علم الحلال والحرام دون علم الغيب","علم ما كان فقط من أخبار السابقين"]'::jsonb, 1, 20, 6, 'multi', 'جاء في ''الكافي'' للكليني في باب أن الأئمة عندهم جميع العلوم التي خرجت إلى الملائكة والأنبياء والرسل، أن الإمام يعلم ما كان وما يكون وما هو كائن إلى يوم القيامة، وهو علم موهوب من الله.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما الفرق بين عصمة الأنبياء وعصمة الأئمة في العقيدة الإمامية وفق الشيخ المفيد؟', '["عصمة الأنبياء مطلقة بينما عصمة الأئمة مقيدة بالشؤون الدينية","الأنبياء معصومون قبل النبوة أما الأئمة فمعصومون بعد تعيينهم فقط","لا فرق بينهما في المرتبة والمستوى","عصمة الأنبياء تشمل تبليغ الوحي وعصمة الأئمة تشمل حفظ الشريعة وتطبيقها"]'::jsonb, 3, 20, 7, 'multi', 'أوضح الشيخ المفيد في ''أوائل المقالات'' أن الأنبياء معصومون في تلقي الوحي وتبليغه، بينما الأئمة معصومون في حفظ الشريعة وتفسيرها وتطبيقها وقيادة الأمة، وكلاهما معصوم من الذنوب والخطأ.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'لماذا يشترط الإمامية أن يكون الإمام منصوصاً عليه من قِبَل الله أو النبي أو الإمام السابق؟', '["لأن العصمة لا تُعرف إلا بالنص الإلهي إذ لا يطلع عليها البشر","لأن الأمة غير قادرة على الاختيار السليم دون وصاية إلهية","لأن الاختيار الشعبي يؤدي إلى الفتنة والاقتتال","لأن الأئمة من نسل قريش ولا بد من توثيق النسب"]'::jsonb, 0, 20, 8, 'multi', 'يستند الإمامية إلى أن العصمة صفة باطنية لا يعلمها إلا الله، ولا يمكن للبشر التحقق منها، فلا بد من نص إلهي أو نبوي يعيّن المعصوم، وهو ما قرره المحقق الطوسي وابن ميثم البحراني.', 'الإمامة والعصمة');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_7, 'ما موقف الإمامية من نسيان الإمام المعصوم للأحكام الشرعية؟', '["يجوز على الإمام النسيان في الشؤون الدنيوية دون الدينية","النسيان جائز على الإمام كالبشر العاديين لأنه بشر","الإمام معصوم من النسيان في الأحكام الشرعية لأن نسيانه يُضل الأمة","النسيان جائز لكن الإمام يُنبَّه إليه فوراً بالوحي"]'::jsonb, 2, 20, 9, 'multi', 'ذهب الإمامية إلى أن الإمام لا ينسى الأحكام الشرعية لأن نسيانه يُفضي إلى ضلال الأمة وتناقض السنة، وهو ما ينافي الغرض من الإمامة، كما أكد ذلك الشيخ المفيد والعلامة الحلي في مصنفاتهم العقدية.', 'الإمامة والعصمة');
END $$;

DO $$
DECLARE
  v_quiz_id_8 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أحكام الصلاة الواجبة والمستحبة ومبطلاتها', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_8;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما هو عدد الصلوات اليومية الواجبة في الفقه الجعفري؟', '["خمس صلوات","ست صلوات","ثلاث صلوات","أربع صلوات"]'::jsonb, 0, 20, 0, 'multi', 'الصلوات اليومية الواجبة خمس: الصبح والظهر والعصر والمغرب والعشاء، وهذا متفق عليه في الفقه الجعفري.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'كم عدد ركعات صلاة الصبح في الفقه الجعفري؟', '["أربع ركعات","ركعة واحدة","ثلاث ركعات","ركعتان"]'::jsonb, 3, 20, 1, 'multi', 'صلاة الصبح ركعتان، وهي من الصلوات التي لا تُقصر في السفر لأنها أصلاً ركعتان.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما الحكم الشرعي لصلاة الجمعة في زمن الغيبة الكبرى عند أكثر فقهاء الإمامية؟', '["مستحبة","واجبة تخييرية بينها وبين الظهر","واجبة عينية","محرمة"]'::jsonb, 1, 20, 2, 'multi', 'ذهب أكثر فقهاء الإمامية إلى أن صلاة الجمعة في زمن الغيبة واجبة تخييرية، أي يتخير المكلف بين إقامتها وبين صلاة الظهر.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'أيٌّ من الآتي يُعدّ من مبطلات الصلاة في الفقه الجعفري؟', '["الحدث الأصغر أثناء الصلاة","السعال الاضطراري","البكاء خشيةً من الله","الالتفات اليسير بالوجه"]'::jsonb, 0, 20, 3, 'multi', 'الحدث الأصغر كالبول أو الريح أثناء الصلاة يُبطلها، بخلاف البكاء خشيةً من الله والالتفات اليسير والسعال الاضطراري فلا تُبطل الصلاة.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما الذي يُعدّ شرطاً في صحة الصلاة من حيث القبلة عند الإمامية؟', '["لا يشترط استقبال القبلة في الصلاة المفروضة","استقبال عين الكعبة فقط","الاستقبال الظني للقبلة بالاجتهاد عند تعذر اليقين","الصلاة نحو الشمال دائماً"]'::jsonb, 2, 20, 4, 'multi', 'يشترط استقبال القبلة في الصلاة، ويكفي الظن الحاصل بالاجتهاد أو الأمارات عند تعذر اليقين، وإلا صلى إلى الجهات الأربع إن لم يتمكن من الاجتهاد.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما حكم الكلام العمدي في أثناء الصلاة في الفقه الجعفري؟', '["لا يضر إذا كان يسيراً","مكروه فقط","يوجب سجدتي السهو فقط","يُبطل الصلاة"]'::jsonb, 3, 20, 5, 'multi', 'الكلام العمدي بحرفين فأكثر من غير ضرورة يُبطل الصلاة في الفقه الجعفري، وهو من قواطع الصلاة المتفق عليها.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما هي النافلة اليومية المرتبطة بصلاة الفجر والتي يُؤكد عليها الفقه الجعفري؟', '["صلاة الأوابين","ركعتا الفجر (نافلة الفجر)","صلاة الليل","صلاة الوتر"]'::jsonb, 1, 20, 6, 'multi', 'ركعتا الفجر هما النافلة المؤكدة التي تُصلى قبل فريضة الصبح، وهي من النوافل الراتبة المشددة عليها في الروايات الجعفرية.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'كم عدد ركعات نافلة الليل الكاملة في الفقه الجعفري؟', '["ست ركعات","ثلاث عشرة ركعة","إحدى عشرة ركعة","ثماني ركعات"]'::jsonb, 2, 20, 7, 'multi', 'نافلة الليل إحدى عشرة ركعة: ثماني ركعات صلاة الليل، وركعتا الشفع، وركعة الوتر، وهذا ما أكدته روايات أهل البيت عليهم السلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'ما الحكم في من شك بين الثلاث والأربع في الصلاة الرباعية في الفقه الجعفري؟', '["يبني على الأكثر ويتم الصلاة ثم يحتاط بركعة منفصلة","يعيد الصلاة من البداية","شكه لا حكم له","يبني على الأقل ويأتي بركعة"]'::jsonb, 0, 20, 8, 'multi', 'من شك بين الثلاث والأربع يبني على الأربع ويُتم صلاته، ثم يأتي بصلاة الاحتياط ركعة قائماً أو ركعتين جالساً، وهذا من أحكام الشكوك الصحيحة.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_8, 'أيٌّ من الآتي لا يُبطل الصلاة في الفقه الجعفري؟', '["الضحك القهقهي عمداً","ترك ركن من أركان الصلاة عمداً","استدبار القبلة عمداً","نسيان التشهد الأخير والتذكر بعد السلام"]'::jsonb, 3, 20, 9, 'multi', 'نسيان التشهد الأخير والتذكر بعده لا يُبطل الصلاة، بل يجب قضاؤه وسجدتا السهو. أما القهقهة وترك الركن عمداً واستدبار القبلة فكلها مبطلات.', 'فقه جعفري عملي');
END $$;

DO $$
DECLARE
  v_quiz_id_9 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أحكام الصوم ونوافل شهر رمضان والمفطرات', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_9;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما هو الحكم الشرعي لمن أفطر في شهر رمضان متعمداً بغير عذر شرعي؟', '["لا شيء عليه إن تاب","تجب عليه الكفارة المغلظة مع القضاء","يجب عليه الاستغفار فقط","يجب عليه القضاء فقط"]'::jsonb, 1, 20, 0, 'multi', 'من أفطر متعمداً في رمضان بغير عذر تجب عليه الكفارة المغلظة وهي عتق رقبة أو صيام شهرين متتابعين أو إطعام ستين مسكيناً مع وجوب القضاء، وفق المشهور من الفقه الجعفري.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما هي النية المعتبرة في صوم شهر رمضان وفق الفقه الجعفري؟', '["النية من أي وقت قبل الفجر أو بعده في أثناء النهار مطلقاً","يكفي القصد العام في أول الشهر عن جميع أيامه","النية بعد الزوال جائزة مطلقاً","النية قبل الفجر الصادق أو أثناء النهار قبل الزوال لمن لم يأت بمفطر"]'::jsonb, 3, 20, 1, 'multi', 'يشترط الفقه الجعفري تبييت النية قبل الفجر، وللناسي أو الجاهل أن ينوي قبل الزوال ما لم يأتِ بمفطر، وهو ما ذهب إليه السيد الخوئي والسيد السيستاني.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'أيٌّ من التالية يُعدّ من المفطرات عند الإمامية؟', '["شم الروائح العطرة","التبرع بالدم","الحقنة الشرجية","السباحة في الماء"]'::jsonb, 2, 20, 2, 'multi', 'الحقنة الشرجية مفطرة عند المشهور من فقهاء الإمامية لأنها إدخال شيء إلى الجوف، أما شم العطور والتبرع بالدم والسباحة فلا تُبطل الصوم على الأصح.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما حكم الصوم في السفر وفق الفقه الجعفري؟', '["يصح الصوم في السفر إن نذره قبل السفر فقط","يحرم الصوم في السفر ويجب القضاء","يتخير المسافر بين الصوم والإفطار","يجوز الصوم في السفر مطلقاً"]'::jsonb, 1, 20, 3, 'multi', 'ذهب المشهور من فقهاء الإمامية إلى بطلان صوم رمضان في السفر الذي توجب فيه قصر الصلاة، ويجب على المسافر الإفطار وقضاء تلك الأيام بعد رمضان.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما هي نوافل شهر رمضان الثابتة عند الإمامية في كل ليلة؟', '["ثماني ركعات","أربع ركعات","ست ركعات","عشرون ركعة"]'::jsonb, 3, 20, 4, 'multi', 'المشهور عند الإمامية استحباب عشرين ركعة في كل ليلة من ليالي رمضان، تُوزَّع على أوقات مخصوصة، وهي مستحبة لا واجبة، وقد وردت في روايات متعددة.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما حكم الارتماس في الماء للصائم عند الإمامية؟', '["محرم ومفطر عند المشهور","مفطر في النهار مباح في الليل","جائز مطلقاً","مكروه ولا يُفطر"]'::jsonb, 0, 20, 5, 'multi', 'ذهب المشهور من فقهاء الإمامية إلى أن الارتماس في الماء بغمس الرأس كله دفعةً واحدة مفطر ومحرم على الصائم، وهو رأي السيد الخوئي والسيد السيستاني.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما الحكم الشرعي لمن أجنب في ليل رمضان وتعمد تأخير الغسل حتى طلع الفجر؟', '["صومه صحيح ولا شيء عليه","صومه باطل ويجب القضاء فقط","يستحب له الاستغفار ولا شيء آخر","صومه باطل ويجب القضاء والكفارة"]'::jsonb, 1, 20, 6, 'multi', 'من تعمد البقاء على الجنابة حتى طلع الفجر في شهر رمضان بطل صومه عند المشهور من الإمامية ووجب عليه القضاء، واختلفوا في وجوب الكفارة والأحوط وجوبها.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما حكم إفطار المريض الذي يتضرر من الصوم في شهر رمضان؟', '["يجب عليه الصوم ولو بلغ الضرر حداً شديداً","يجوز له الإفطار ولا قضاء عليه","يتصدق عوضاً عن القضاء فقط","يجب عليه الإفطار ويقضي بعد زوال العذر"]'::jsonb, 3, 20, 7, 'multi', 'يجب على المريض الذي يتضرر من الصوم الإفطار، فإذا زال مرضه قبل انتهاء رمضان وجب عليه القضاء، أما من استمر مرضه حتى رمضان القادم فيسقط عنه القضاء وتجب الفدية.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'أيٌّ مما يلي لا يُعدّ من المفطرات في الفقه الجعفري؟', '["إيصال الغبار الغليظ إلى الحلق","الكذب على الله أو النبي أو الأئمة","شم الرياحين والأزهار","استعمال قطرة العين الواصلة إلى الحلق"]'::jsonb, 2, 20, 8, 'multi', 'شم الرياحين والأزهار لا يُفطر الصوم عند الإمامية، في حين أن إيصال الغبار الغليظ إلى الحلق عمداً والكذب على المعصومين والقطرة الواصلة إلى الحلق مفطرات عند المشهور.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_9, 'ما هي الليالي التي تُضاعف فيها نوافل رمضان ويُستحب فيها إحياؤها بالعبادة عند الإمامية؟', '["ليالي القدر وهي التاسعة عشرة والحادية والعشرون والثالثة والعشرون","ليالي الأيام الفردية فقط","ليالي الجمعة فقط","الليالي العشر الأولى فقط"]'::jsonb, 0, 20, 9, 'multi', 'تُعدّ ليالي القدر عند الإمامية هي ليلة التاسع عشر وليلة الحادي والعشرين وليلة الثالث والعشرين من رمضان، وتُستحب فيها العبادة والإحياء ويُضاعف فيها ثواب النوافل وفق الروايات المعتبرة.', 'فقه جعفري عملي');
END $$;

DO $$
DECLARE
  v_quiz_id_10 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أحكام الخمس وموارد وجوبه الشائعة', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_10;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما هي نسبة الخمس الواجب إخراجه من أرباح المكاسب بعد استثناء مؤونة السنة؟', '["الخُمس أي خمس المال","الربع","الثلث","العشر"]'::jsonb, 0, 20, 0, 'multi', 'يجب إخراج خُمس ما زاد من أرباح المكاسب عن مؤونة السنة وهو الخمس أي 20 بالمئة وفق ما نصّ عليه الفقه الجعفري استناداً إلى آية الغنيمة.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'استناداً إلى الفقه الجعفري كيف يُقسَّم الخمس على المستحقين؟', '["يُوزَّع على ستة أسهم متساوية","يُدفع كله للمرجع الديني","نصفان متساويان بين الفقراء والأيتام فقط","نصف لسهم الإمام ونصف يُقسم على السادة الفقراء والأيتام وأبناء السبيل"]'::jsonb, 3, 20, 1, 'multi', 'يُقسَّم الخمس نصفين: سهم الإمام ويكون في زمن الغيبة لمرجع التقليد، وسهم السادة يُوزَّع على بني هاشم من فقراء وأيتام وأبناء سبيل وفق الفقه الإمامي.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'أيّ من الموارد التالية يُعدّ من موارد وجوب الخمس في الفقه الجعفري؟', '["الهدايا والهبات مطلقاً","المال الذي يختلط الحلال فيه بالحرام ولا يُعرف صاحبه","الإرث المعتاد من الأقارب","الزكاة المدفوعة للفقراء"]'::jsonb, 1, 20, 2, 'multi', 'من موارد الخمس المال المختلط بالحرام إذا جهل مقداره وصاحبه فيجب إخراج خمسه تطهيراً له وفق الفقه الجعفري.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما المقصود بـ''مؤونة السنة'' التي تُستثنى من أرباح المكاسب قبل احتساب الخمس؟', '["ثمن البيت والسيارة فقط","ما يُدفع ضريبةً للدولة","المصاريف الضرورية وما يليق بشأن المكلف وعياله خلال السنة","ما يُنفق على الأعمال الخيرية فقط"]'::jsonb, 2, 20, 3, 'multi', 'المؤونة هي النفقات المعتادة التي يحتاجها المكلف وعياله خلال السنة مما يليق بشأنه عرفاً من مأكل وملبس ومسكن وتعليم وغيرها.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما حكم الأرض التي يشتريها ذمّيٌّ من مسلم في الفقه الجعفري؟', '["لا خمس فيها مطلقاً","يُكتفى بدفع الزكاة عنها","تُصادَر لبيت المال","يجب على الذمّي إخراج خمسها"]'::jsonb, 3, 20, 4, 'multi', 'ذهب مشهور فقهاء الإمامية إلى أن الأرض التي يشتريها الذمّي من المسلم يجب فيها الخمس ويكون على الذمّي إخراجه.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما هو حكم المعادن التي يستخرجها الإنسان في الفقه الجعفري من حيث الخمس؟', '["يجب فيها الخمس كاملاً دون خصم أي تكاليف","يجب فيها الخمس بعد إخراج مؤونة الاستخراج إذا بلغت النصاب","يجب فيها ربع العشر فقط","لا خمس فيها وإنما تجب الزكاة"]'::jsonb, 1, 20, 5, 'multi', 'المعادن من موارد الخمس الستة، ويجب إخراج خمسها بعد استثناء مؤونة الاستخراج إذا بلغت النصاب المحدد شرعاً.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما السنة الخمسية في اصطلاح الفقه الجعفري؟', '["تحديد سنة مالية للمكلف يُحاسَب فيها على أرباحه ويُخرج خمس ما زاد عن مؤونتها","مدة خمس سنوات لتسديد الخمس بالتقسيط","الفترة الخمسية التي يُراجَع فيها المرجع الديني","الفترة التي تسقط بعدها المطالبة بالخمس"]'::jsonb, 0, 20, 6, 'multi', 'السنة الخمسية هي السنة المالية التي يعيّنها المكلف لنفسه أو يعيّنها له المرجع، وفي نهايتها يحاسب نفسه على أرباحه ويُخرج خمس ما زاد عن مؤونته.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما حكم الكنز الذي يعثر عليه شخص في الفقه الجعفري؟', '["تجب فيه الزكاة لا الخمس","يُسلَّم بالكامل لبيت المال","يعود بالكامل لصاحبه الواجد ولا خمس فيه","يجب إخراج خمسه بعد استثناء مؤونة استخراجه إذا بلغ النصاب"]'::jsonb, 3, 20, 7, 'multi', 'الكنز من موارد وجوب الخمس الستة، ويُخرج خمسه إذا بلغ نصابه المحدد بعشرين ديناراً ذهباً أو مائتي درهم فضة وفق المشهور.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما موقف الفقه الجعفري من الإرث الذي لم يكن متوقعاً ولم يُحتسب في الميزانية الاعتيادية للمكلف؟', '["لا خمس فيه مطلقاً لأن الإرث لا خمس فيه بالإجماع","يُعامَل معاملة الزكاة لا الخمس","يرى بعض المراجع وجوب الخمس في الإرث غير المتوقع الذي لم يُعهد عادةً","يجب فيه نصف الخمس فقط"]'::jsonb, 2, 20, 8, 'multi', 'الإرث المتعارف لا خمس فيه عند المشهور، غير أن بعض المراجع المعاصرين يرون وجوب الخمس في الإرث الكثير غير المعتاد الذي يعدّه العرف ربحاً طارئاً.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_10, 'ما حكم من تأخّر في أداء الخمس عن موعده المحدد دون عذر شرعي؟', '["يُضاعَف عليه المبلغ بمرور الوقت","يبقى الخمس ديناً في ذمته ويأثم بالتأخير وعليه الأداء مهما طال الزمن","يسقط عنه الخمس ولا شيء عليه","يكفي الاستغفار عن التأخير"]'::jsonb, 1, 20, 9, 'multi', 'الخمس حق شرعي ثابت في الذمة لا يسقط بالتأخير، ويأثم المكلف على التسويف، ويبقى ملزماً بأدائه في أي وقت وفق نصوص الفقه الإمامي.', 'فقه جعفري عملي');
END $$;

DO $$
DECLARE
  v_quiz_id_11 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أحكام الزكاة والمعاملات المالية المعاصرة', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_11;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما هو النصاب الأول للذهب الذي تجب فيه الزكاة وفق الفقه الجعفري؟', '["خمسة عشر مثقالاً","خمسة عشر ديناراً","عشرة مثاقيل","عشرون مثقالاً"]'::jsonb, 3, 20, 0, 'multi', 'النصاب الأول للذهب عشرون مثقالاً صيرفياً، وفيه نصف مثقال زكاةً، وهذا ما أجمع عليه فقهاء الإمامية استناداً إلى روايات أهل البيت عليهم السلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'هل تجب الزكاة في الأوراق النقدية المعاصرة وفق رأي أغلب مراجع الشيعة الإمامية؟', '["تجب وجوباً قطعياً كالذهب والفضة","تجب إذا بلغت نصاب الفضة فقط","لا تجب لأنها ليست من الأصناف التسعة","تجب احتياطاً استحبابياً فقط"]'::jsonb, 2, 20, 1, 'multi', 'أغلب مراجع الإمامية يرون أن الزكاة الواجبة محددة بتسعة أصناف، والأوراق النقدية ليست منها، غير أنهم يستحبون إخراجها تورعاً، ومنهم السيد السيستاني والسيد الخامنئي.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما الشرط الزمني اللازم لوجوب زكاة الذهب والفضة في الفقه الجعفري؟', '["مرور حول كامل وهو اثنا عشر شهراً قمرياً","مرور ستة أشهر هجرية","لا يشترط مرور حول","مرور سنة ميلادية كاملة"]'::jsonb, 0, 20, 2, 'multi', 'يشترط الفقه الجعفري مرور الحول أي اثني عشر شهراً قمرياً على بلوغ النصاب بقاءً واستمراراً، فإن نقص النصاب في أثناء الحول انقطع الحول وبدأ من جديد.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما حكم أرباح التجارة والأعمال الحرة في الفقه الجعفري؟', '["تجب فيها الزكاة والخمس معاً","يجب فيها الخمس لا الزكاة","لا يجب فيها شيء","تجب فيها الزكاة بعد الحول"]'::jsonb, 1, 20, 3, 'multi', 'أرباح التجارة والأعمال تخضع للخمس لا للزكاة في الفقه الجعفري، إذ الخمس يجب في كل فائدة ومكسب بعد استثناء مؤونة السنة، استناداً لقوله تعالى ''واعلموا أنما غنمتم من شيء فإن لله خمسه''.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما حكم الاستثمار في الأسهم من حيث الخمس وفق الفقه الجعفري المعاصر؟', '["لا خمس فيها لأنها ورقية","يجب خمس الربح فقط عند البيع الفعلي","يجب خمس الربح المتحقق عند نهاية السنة الخمسية","يجب خمس رأس المال كله سنوياً"]'::jsonb, 2, 20, 4, 'multi', 'يرى أكثر المراجع وجوب تخميس الأرباح المتحققة سواء وزعت أم أضيفت للرأسمال عند حلول السنة الخمسية، فإن لم تتحقق الأرباح إلا عند البيع وجب الخمس حينئذٍ.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما المقصود بـ''مؤونة السنة'' التي تستثنى قبل إخراج الخمس في الفقه الجعفري؟', '["جميع ما يحتاجه المكلف وعياله في معيشتهم بالمعروف خلال السنة","نفقة الزوجة فقط","ديون الشخص المتراكمة","ربع الدخل السنوي تقديراً"]'::jsonb, 0, 20, 5, 'multi', 'مؤونة السنة هي مجموع ما أنفقه المكلف على نفسه وعياله من مسكن وملبس ومأكل وعلاج ودراسة وما شابه ذلك مما يليق بشأنه عرفاً، وما زاد بعدها يجب خمسه.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما حكم القرض بفائدة ''الربا'' الذي تمارسه البنوك التجارية في الفقه الجعفري؟', '["محرم مطلقاً في جميع الأحوال","جائز بعقد الحيلة الشرعية كالمرابحة والإجارة","جائز إذا كان بين مسلم وكافر","جائز إذا كانت الفائدة دون عشرة بالمئة"]'::jsonb, 1, 20, 6, 'multi', 'الربا محرم في الفقه الجعفري، غير أن المراجع أجازوا التعامل مع البنوك عبر صيغ شرعية كالمرابحة والمضاربة والإجارة والقرض الحسن، فيما يجيز بعضهم أخذ الفائدة من بنوك الدول غير الإسلامية بنية الاستنقاذ.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما الأصناف الثلاثة الأولى من مصارف الزكاة المذكورة في آية ''إنما الصدقات'' وفق ترتيب الآية الكريمة؟', '["الفقراء والغارمون وابن السبيل","المساكين والمؤلفة قلوبهم والغارمون","المساكين والرقاب وفي سبيل الله","الفقراء والمساكين وعاملون عليها"]'::jsonb, 3, 20, 7, 'multi', 'قال تعالى ''إنما الصدقات للفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب والغارمين وفي سبيل الله وابن السبيل''، فالأول الفقراء ثم المساكين ثم العاملون عليها.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما حكم دفع الزكاة إلى الفقيه الجامع للشرائط أو وكيله في زماننا وفق كثير من مراجع الإمامية؟', '["واجب مطلقاً ولا يجوز الدفع لغيره","محرم لأن الزكاة اختصت بالإمام المعصوم فقط","جائز بل مستحب لأنه أعلم بمواردها وقد يكون واجباً في بعض الصور","مستحب لا واجب بأي حال"]'::jsonb, 2, 20, 8, 'multi', 'يرى كثير من المراجع الإمامية أن دفع الزكاة إلى الفقيه الجامع للشرائط أو وكيله مستحب لأنه أعرف بمواضعها، وقد يكون واجباً في حال توقف إقامة الشعائر الاجتماعية على ذلك، وللمكلف في غير ذلك أن يوزعها بنفسه.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_11, 'ما حكم شراء العملات الرقمية المشفرة كالبيتكوين من حيث الخمس وفق الاجتهادات المعاصرة للمراجع الجعفرية؟', '["هي محرمة فلا يترتب عليها حكم شرعي","يجب خمس الربح المتحقق منها ضمن السنة الخمسية كسائر الفوائد","لا خمس فيها لعدم ورودها في النصوص الشرعية","يجب خمس رأس المال فيها خاصةً لكونها مجهولة المالية"]'::jsonb, 1, 20, 9, 'multi', 'أفتى عدد من المراجع المعاصرين كالسيد السيستاني وغيره بأن الربح المتحقق من تداول العملات الرقمية يخضع لأحكام الخمس كسائر الأرباح والفوائد، فيجب إخراج خمس ما زاد عن مؤونة السنة.', 'فقه جعفري عملي');
END $$;

DO $$
DECLARE
  v_quiz_id_12 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أحكام الطهارة الوضوء الغسل والتيمم', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_12;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما هو الترتيب الصحيح لأعضاء الوضوء عند الإمامية الاثني عشرية؟', '["مسح الوجه ثم غسل اليدين ثم مسح الرأس ثم مسح الرجلين","غسل الوجه ثم اليدين من المرفق ثم مسح الرأس ثم مسح الرجلين","غسل الوجه ثم اليدين من الأصابع ثم مسح الرأس ثم الرجلين","غسل الوجه ثم اليدين من الكوع ثم مسح الرأس ثم غسل الرجلين"]'::jsonb, 1, 20, 0, 'multi', 'يجب في الوضوء الجعفري غسل الوجه واليدين من المرفق إلى الأصابع ومسح الرأس ومسح الرجلين من رؤوس الأصابع إلى الكعبين وفق ما دلت عليه الآية الكريمة وروايات أهل البيت عليهم السلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما حكم مسح الرجلين في الوضوء عند الفقه الجعفري؟', '["واجب غسلهما لا مسحهما","يتخير المكلف بين المسح والغسل","واجب من رؤوس الأصابع إلى الكعبين","مستحب ويجوز غسلهما بدلاً منه"]'::jsonb, 2, 20, 1, 'multi', 'يذهب الفقه الجعفري إلى وجوب مسح الرجلين لا غسلهما استناداً إلى قراءة الجر في الآية الكريمة وروايات الأئمة عليهم السلام ومنها ما رواه الكليني في الكافي.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'كم مقدار مسح الرأس الواجب في الوضوء الجعفري؟', '["مسح ربع الرأس فأكثر","مسح نصف الرأس الأمامي","مسح جميع الرأس من الجبهة إلى القفا","مسح بعضه بما يصدق عليه اسم المسح ولو بثلاث أصابع"]'::jsonb, 3, 20, 2, 'multi', 'يكفي في مسح الرأس أن يمسح بعضه بما يصدق عليه المسح عرفاً وهو المشهور عند الإمامية استناداً إلى دلالة الباء في قوله تعالى: ''وامسحوا برؤوسكم'' على التبعيض.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما هي نواقض الوضوء المتفق عليها في الفقه الجعفري؟', '["البول والغائط والريح والنوم والجنابة والحيض","البول والغائط والريح فقط","البول والغائط فقط","الجنابة والحيض والنوم فقط"]'::jsonb, 0, 20, 3, 'multi', 'تشمل نواقض الوضوء عند الإمامية: البول والغائط والريح الخارج من الموضع المعتاد والنوم الغالب على العقل والجنابة والحيض والاستحاضة والنفاس وفقاً لما ورد في المصادر الفقهية كالمبسوط للشيخ الطوسي وشرائع الإسلام للمحقق الحلي.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما هي الأغسال الواجبة في الفقه الجعفري؟', '["غسل الجنابة والحيض والنفاس فقط","غسل الجنابة والحيض والنفاس والاستحاضة ومس الميت وغسل الميت","غسل الجنابة والحيض فقط","غسل الجنابة فقط بوصفه أصل الأغسال"]'::jsonb, 1, 20, 4, 'multi', 'تشمل الأغسال الواجبة في الفقه الجعفري ستة: الجنابة والحيض والنفاس والاستحاضة ومس الميت وغسل الميت كما ذكرها المحقق الحلي في شرائع الإسلام والعلامة الحلي في تذكرة الفقهاء.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما الفرق بين الغسل الترتيبي والغسل الارتماسي في الفقه الجعفري؟', '["لا فرق بينهما في الصحة والأثر","الترتيبي يبدأ بالجانب الأيمن ثم الأيسر ثم الرأس والارتماسي للجنب فقط","الترتيبي للواجب والارتماسي للمستحب فقط","الترتيبي يبدأ بالرأس ثم الجانب الأيمن ثم الأيسر والارتماسي غمر الجسد كله دفعة واحدة"]'::jsonb, 3, 20, 5, 'multi', 'في الغسل الترتيبي يبدأ المكلف بغسل الرأس والرقبة ثم الجانب الأيمن ثم الأيسر أما الارتماسي فيرتمس البدن كله في الماء دفعة واحدة وكلاهما صحيح وفق المشهور في الفقه الجعفري كما في العروة الوثقى للسيد اليزدي.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما شروط التيمم في الفقه الجعفري؟', '["يجوز التيمم متى شاء المكلف بديلاً عن الوضوء","يجوز التيمم عند البرودة الشديدة فقط","تعذر استعمال الماء لعدمه أو الضرر أو الحرج أو ضيق الوقت","يشترط له الحصول على إذن من الفقيه"]'::jsonb, 2, 20, 6, 'multi', 'يجوز التيمم عند تعذر استعمال الماء لأسباب عدة منها: فقدان الماء أو الخوف من الضرر باستعماله أو الحرج الشديد أو ضيق الوقت وذلك استناداً إلى قوله تعالى: ''فلم تجدوا ماء فتيمموا'' وروايات أهل البيت عليهم السلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'على ماذا يصح التيمم في الفقه الجعفري؟', '["كل شيء طاهر حتى الخشب والقماش عند الضرورة","الأرض وما يصدق عليه اسم الأرض كالتراب والرمل والحجر","التراب فقط دون سائر أنواع الأرض","الجص والآجر فقط لأنهما من الأرض المحروقة"]'::jsonb, 1, 20, 7, 'multi', 'يصح التيمم على ما يصدق عليه اسم الأرض من تراب ورمل وحجر وطين وهو المشهور عند الإمامية استناداً إلى ما ورد في روايات الأئمة عليهم السلام ومنها قول الإمام الصادق: ''التراب أحد الطهورين''.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما كيفية التيمم الصحيح وفق الفقه الجعفري؟', '["ضربتان على الأرض الأولى للوجه والثانية لظاهر الكفين مع النية","ضربة واحدة يمسح بها الوجه واليدين معاً","ضربتان للوجه والرأس فقط دون اليدين","ثلاث ضربات للوجه واليدين والرجلين"]'::jsonb, 0, 20, 8, 'multi', 'كيفية التيمم عند الإمامية أن يضرب بيديه على الأرض ضربتين يمسح بالأولى جبهته وجبينيه ويمسح بالثانية ظاهر كفيه اليمنى بالكف اليسرى والعكس وذلك ما أفتى به الشيخ الطوسي والمحقق الحلي وجمهور الفقهاء.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_12, 'ما حكم الوضوء لمن أجنب في الفقه الجعفري؟', '["يجب الوضوء ثم الغسل معاً","يتخير بين الوضوء والغسل عند الجنابة","لا يصح الوضوء مع الجنابة ويجب الغسل بدلاً منه ويغني الغسل عن الوضوء","يصح الوضوء بدلاً عن الغسل عند العجز عنه"]'::jsonb, 2, 20, 9, 'multi', 'يذهب الفقه الجعفري إلى أن الجنابة ترفعها الغسل لا الوضوء وأن غسل الجنابة يغني عن الوضوء فلا يصح ضمهما معاً وذلك استناداً إلى روايات متعددة منها ما رواه الشيخ الطوسي في التهذيب عن الأئمة عليهم السلام.', 'فقه جعفري عملي');
END $$;

DO $$
DECLARE
  v_quiz_id_13 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('المعاملات والتجارة والصيد والأطعمة والأشربة', 'إسلاميات', 'فقه جعفري عملي', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_13;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما هو شرط صحة البيع في الفقه الجعفري من حيث المتعاقدين؟', '["أن يكون البائع بالغاً عاقلاً مختاراً مالكاً أو مأذوناً","يكفي أن يكون البائع مسلماً فقط","يشترط أن يكون كلاهما من الذكور البالغين","يكفي الرضا الباطني دون إظهار"]'::jsonb, 0, 20, 0, 'multi', 'يشترط في المتعاقدين البلوغ والعقل والاختيار والملكية أو الإذن، وهذا مما اتفق عليه فقهاء الإمامية كالشيخ الطوسي في المبسوط والمحقق الحلي في شرائع الإسلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما حكم بيع الخمر في الفقه الجعفري؟', '["جائز إذا كان البائع غير مسلم","مكروه وليس محرماً","حرام وباطل مطلقاً","جائز للمضطر فقط"]'::jsonb, 2, 20, 1, 'multi', 'بيع الخمر باطل ومحرم بالإجماع في الفقه الجعفري، إذ لا يجوز بيع ما لا منفعة محللة فيه، كما نص على ذلك المحقق الحلي في شرائع الإسلام وصاحب الجواهر.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما المقصود بخيار المجلس في الفقه الجعفري؟', '["حق الفسخ يمتد ثلاثة أيام من وقت العقد","خيار يثبت للمشتري وحده دون البائع","هو خيار لا يثبت إلا في بيع الحيوان","حق كل من المتبايعين في فسخ البيع ما داما في المجلس قبل التفرق"]'::jsonb, 3, 20, 2, 'multi', 'خيار المجلس يثبت لكلا المتبايعين ما لم يتفرقا، مستنداً إلى الروايات عن أهل البيت عليهم السلام، وقد أقره المحقق الحلي والشيخ الأنصاري في المكاسب.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما حكم الصيد بالآلة دون ذكر اسم الله عليها في الفقه الجعفري؟', '["لا يحل أكل الصيد إذا لم يُذكر اسم الله عند إرسال الآلة","يحرم فقط إذا كان الصائد مسلماً","يحل الصيد حتى لو لم يُسمَّ لأن التسمية مستحبة فقط","يحل إذا ذكر اسم الله عند تناول الطعام"]'::jsonb, 0, 20, 3, 'multi', 'يشترط في الفقه الجعفري ذكر اسم الله عند إرسال الآلة أو الكلب المعلَّم، فإن تُرك عمداً لم يحل الصيد، وهذا مذهب المشهور كما في شرائع الإسلام وجواهر الكلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما حكم أكل السمك الذي مات حتف أنفه خارج الماء في الفقه الجعفري؟', '["يحرم إلا إذا كان من نوع السمك المقشور","يحل أكله لأن ذكاته إخراجه حياً من الماء","يحرم لأنه لم يذبح ذبحاً شرعياً","يحل فقط إذا مات في الشبكة"]'::jsonb, 1, 20, 4, 'multi', 'ذكاة السمك إخراجه من الماء حياً وإن مات بعد ذلك، فيحل أكله بشرط أن يكون له فلس. وهذا مذهب المشهور في الفقه الجعفري استناداً للروايات عن الأئمة عليهم السلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما الموقف الفقهي الجعفري من شرط الربا في عقد القرض؟', '["يجوز بالتراضي بين المسلمين","القرض والشرط كلاهما باطلان","يجوز اشتراط الزيادة إذا كانت يسيرة","الشرط باطل والقرض صحيح على المشهور"]'::jsonb, 3, 20, 5, 'multi', 'اشتراط الزيادة في القرض ربا محرم، والمشهور عند الإمامية أن الشرط يبطل دون أن يسري البطلان إلى أصل العقد، كما حققه الشيخ الأنصاري في المكاسب وصاحب الجواهر.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما حكم بيع الكلب في الفقه الجعفري؟', '["يجوز بيع جميع أنواع الكلاب","يحرم بيع كلب الصيد لأنه لا ثمن له","لا يجوز بيع الكلب غير المعلَّم للصيد، ويجوز بيع كلب الصيد المعلَّم","يجوز بيع الكلب الحارس للزرع فقط"]'::jsonb, 2, 20, 6, 'multi', 'المشهور في الفقه الجعفري أن الكلب غير المعلَّم لا يقع عليه البيع لعدم المنفعة المحللة، أما كلب الصيد المعلَّم فيجوز بيعه وله ثمن، كما في شرائع الإسلام وجواهر الكلام.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما شرط حِل الذبيحة في الفقه الجعفري من حيث الذابح؟', '["يشترط أن يكون الذابح مسلماً أو في حكمه، ولا تحل ذبيحة الكافر غير الكتابي","يشترط أن يكون الذابح ذكراً بالغاً فقط","تحل ذبيحة كل من ذكر اسم الله مهما كان دينه","تحل ذبيحة أهل الكتاب مطلقاً"]'::jsonb, 0, 20, 7, 'multi', 'يشترط في الذابح الإسلام أو ما في حكمه، ولا تحل ذبيحة الكافر على المشهور في الفقه الجعفري، وأما أهل الكتاب فذبيحتهم محرمة عند أكثر الفقهاء الإماميين كالمحقق الحلي وصاحب الجواهر.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما حكم شرب عصير العنب إذا غلى واشتد قبل أن يذهب ثلثاه في الفقه الجعفري؟', '["يحل إذا طُبخ بالنار مجدداً","يكره شربه فقط ولا يحرم","يحل شربه إذا لم يُسكر","يحرم شربه ويصير نجساً على المشهور"]'::jsonb, 3, 20, 8, 'multi', 'إذا غلى عصير العنب واشتد حرم شربه ويصير نجساً على المشهور بين فقهاء الإمامية، ويحل ويطهر إذا ذهب ثلثاه بالنار، كما نص عليه العلامة الحلي وصاحب الجواهر.', 'فقه جعفري عملي');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_13, 'ما الحكم في الفقه الجعفري إذا اشترى شخص سلعة بشرط الخيار لمدة ثلاثة أيام ثم مات في أثناء المدة؟', '["يبطل العقد كله بوفاة أحد المتعاقدين","ينتقل خيار الشرط إلى الورثة ويقومون مقامه","يحق للبائع فسخ العقد فوراً بموت المشتري","يسقط الخيار بموت صاحبه ولا ينتقل"]'::jsonb, 1, 20, 9, 'multi', 'المشهور في الفقه الجعفري أن خيار الشرط يورَّث وينتقل إلى الورثة، فيقوم الوارث مقام الموروث في استعمال الخيار خلال المدة المتبقية، كما حققه الشيخ الأنصاري في المكاسب.', 'فقه جعفري عملي');
END $$;

DO $$
DECLARE
  v_quiz_id_14 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('أسباب النزول وآيات الأحكام', 'إسلاميات', 'علوم القرآن', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_14;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما المقصود بـ''أسباب النزول'' في علوم القرآن؟', '["أسماء الصحابة الذين حفظوا القرآن","الأحداث والوقائع التي نزلت الآيات بسببها أو في سياقها","المراحل الزمنية لنزول القرآن الكريم","ترتيب الآيات في المصحف الشريف"]'::jsonb, 1, 20, 0, 'multi', 'أسباب النزول هي الأحداث والوقائع التي نزلت الآيات القرآنية بمناسبتها أو ردًا عليها، وهي علم مستقل من علوم القرآن يُعين على فهم معاني الآيات وتفسيرها.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما الأثر الفقهي لمعرفة سبب نزول الآية عند الفقهاء الجعفريين؟', '["يجعل الآية خاصة بالشخص الذي نزلت بسببه فقط","يُلغي الحاجة إلى الأحاديث الواردة عن أهل البيت عليهم السلام","يُساعد في تحديد المراد من الآية وتقييد عمومها أو إطلاقها","يُحدد ناسخ الآية ومنسوخها دائمًا"]'::jsonb, 2, 20, 1, 'multi', 'معرفة سبب النزول تُعين الفقيه على فهم مقصد الآية، وقد يُقيّد به الإطلاق أو يُخصص به العموم، وإن كانت القاعدة المشهورة أن ''العبرة بعموم اللفظ لا بخصوص السبب''.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما الآية المعروفة بـ''آية الولاية'' التي يستدل بها الفقهاء الجعفريون على إمامة علي عليه السلام؟', '["آية 1 من سورة النساء: ''يا أيها الناس اتقوا ربكم...''","آية 3 من سورة المائدة: ''اليوم أكملت لكم دينكم...''","آية 67 من سورة المائدة: ''يا أيها الرسول بلّغ ما أنزل إليك...''","آية 55 من سورة المائدة: ''إنما وليكم الله ورسوله والذين آمنوا...''"]'::jsonb, 3, 20, 2, 'multi', 'آية 55 من سورة المائدة تُعرف بآية الولاية، ويرى الفقهاء الجعفريون أنها نزلت في الإمام علي عليه السلام حين تصدّق بخاتمه وهو راكع، وهو دليل على ولايته.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما سبب نزول آية التبليغ في سورة المائدة (الآية 67) وفق الروايات الواردة في المصادر الجعفرية؟', '["نزلت في سياق الدعوة الجهرية في مكة المكرمة","نزلت بمناسبة أمر النبي صلى الله عليه وآله بإعلان ولاية علي عليه السلام في غدير خم","نزلت لأمر النبي بتبليغ أحكام الزكاة للمسلمين","نزلت لحث النبي على تبليغ أحكام الحج الأكبر"]'::jsonb, 1, 20, 3, 'multi', 'تُجمع الروايات الجعفرية على أن آية التبليغ نزلت في غدير خم لأمر النبي صلى الله عليه وآله بالإعلان الصريح عن ولاية الإمام علي عليه السلام، وهو ما فعله النبي في حجة الوداع.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما القاعدة الأصولية المتعلقة بعلاقة سبب النزول بالحكم المستفاد من الآية؟', '["العبرة بعموم اللفظ لا بخصوص السبب","السبب يُلغي الحكم إذا زال موضوعه","السبب ينسخ الآية عند انتهاء الواقعة","العبرة بخصوص السبب لا بعموم اللفظ"]'::jsonb, 0, 20, 4, 'multi', 'القاعدة الأصولية المشهورة عند الفقهاء هي ''العبرة بعموم اللفظ لا بخصوص السبب''، أي أن الحكم المستفاد من الآية يشمل كل من ينطبق عليه اللفظ وليس فقط من نزلت بسببه.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما الآية القرآنية المعروفة بـ''آية التطهير'' ويستدل بها على عصمة أهل البيت عليهم السلام؟', '["الآية 61 من سورة آل عمران: ''فقل تعالوا ندع أبناءنا وأبناءكم...''","الآية 55 من سورة المائدة: ''إنما وليكم الله ورسوله...''","الآية 7 من سورة الحشر: ''وما آتاكم الرسول فخذوه...''","الآية 33 من سورة الأحزاب: ''إنما يريد الله ليذهب عنكم الرجس أهل البيت...''"]'::jsonb, 3, 20, 5, 'multi', 'آية التطهير هي الآية 33 من سورة الأحزاب، وتُعدّ من أبرز الأدلة على عصمة أهل البيت عليهم السلام، ويرى الجعفريون أن المقصود بـ''أهل البيت'' هم النبي وعلي وفاطمة والحسن والحسين عليهم السلام.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما المقصود بـ''آيات الأحكام'' في علوم الفقه الجعفري؟', '["الآيات المتعلقة بالعقيدة والتوحيد فقط","الآيات القرآنية التي تتضمن أحكامًا شرعية فقهية عبادية أو معاملاتية","الآيات التي نسخت أحكام التوراة والإنجيل","الآيات التي تتحدث عن قصص الأنبياء والأمم السابقة"]'::jsonb, 1, 20, 6, 'multi', 'آيات الأحكام هي الآيات القرآنية التي تتضمن أحكامًا شرعية تكليفية أو وضعية، وتشمل العبادات والمعاملات والأحوال الشخصية وغيرها، وقد أُفرد لها علم مستقل يُسمى ''فقه القرآن'' أو ''آيات الأحكام''.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما الكتاب الفقهي الجعفري الشهير المخصص لدراسة آيات الأحكام؟', '["الروضة البهية في شرح اللمعة الدمشقية","المبسوط في فقه الإمامية للشيخ الطوسي","كنز العرفان في فقه القرآن للفاضل المقداد","شرائع الإسلام للمحقق الحلي"]'::jsonb, 2, 20, 7, 'multi', 'كتاب ''كنز العرفان في فقه القرآن'' للفاضل المقداد السيوري الحلي (ت 826هـ) هو من أبرز المصنفات الجعفرية المتخصصة في استنباط الأحكام الفقهية من آيات القرآن الكريم.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما سبب نزول آية المباهلة (آل عمران: 61) وما دلالتها عند الجعفريين؟', '["نزلت لمباهلة نصارى نجران، وتدل على فضل علي وفاطمة والحسنين عليهم السلام","نزلت في سياق الحوار مع المشركين في مكة المكرمة","نزلت لمباهلة يهود المدينة الذين أنكروا نبوة محمد صلى الله عليه وآله","نزلت لإثبات أفضلية المسلمين على المنافقين"]'::jsonb, 0, 20, 8, 'multi', 'نزلت آية المباهلة حين جاء وفد نصارى نجران للجدال في شأن عيسى عليه السلام، فدعاهم النبي للمباهلة وأحضر عليًا وفاطمة والحسن والحسين، مما يدل على منزلتهم الرفيعة عند الله.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_14, 'ما الحكم الفقهي الذي استنبطه الفقهاء الجعفريون من آية ''وأمرهم شورى بينهم'' (الشورى: 38)؟', '["تنسخ الآيات الدالة على ولاية أهل البيت عليهم السلام","تدل على إلزامية الشورى في جميع القرارات الفردية","تدل على وجوب الشورى في تعيين الإمام والحاكم","لا تدل على مشروعية الشورى في تعيين الإمام لأن الإمامة نص إلهي لا اختيار بشري"]'::jsonb, 3, 20, 9, 'multi', 'يرى الفقهاء الجعفريون أن آية الشورى واردة في سياق صفات المؤمنين في شؤونهم الدنيوية، ولا تدل على مشروعية الشورى في تعيين الإمام، لأن الإمامة عندهم منصب إلهي يُعيّن بالنص لا بالاختيار.', 'علوم القرآن');
END $$;

DO $$
DECLARE
  v_quiz_id_15 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('المكي والمدني وتاريخ جمع القرآن', 'إسلاميات', 'علوم القرآن', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_15;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما المعيار الراجح عند جمهور العلماء في تعريف المكي والمدني؟', '["ما نزل في الليل وما نزل في النهار","ما نزل في مكة وما نزل في المدينة","ما نزل قبل الهجرة وما نزل بعدها","ما خوطب به أهل مكة وما خوطب به أهل المدينة"]'::jsonb, 2, 20, 0, 'multi', 'الراجح عند جمهور العلماء أن المكي ما نزل قبل الهجرة النبوية ولو في غير مكة، والمدني ما نزل بعد الهجرة ولو في غير المدينة، وهذا المعيار الزمني هو الأدق والأشمل.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'أي السور الآتية تُعدّ من السور المدنية باتفاق؟', '["سورة الفاتحة","سورة البقرة","سورة الضحى","سورة الإخلاص"]'::jsonb, 1, 20, 1, 'multi', 'سورة البقرة من أوائل السور التي نزلت بعد الهجرة في المدينة المنورة، وهي مدنية باتفاق العلماء، وتتضمن أحكام الصيام والجهاد والمعاملات.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما السمة الغالبة على السور المكية من حيث المضمون؟', '["تنظيم شؤون الدولة والجهاد","تفصيل أحكام المواريث والحدود","تفصيل أحكام الزواج والطلاق","الدعوة إلى التوحيد وتقرير العقيدة وقصص الأنبياء"]'::jsonb, 3, 20, 2, 'multi', 'السور المكية تتسم بغلبة الدعوة إلى التوحيد وإثبات الرسالة والبعث والنشور، والرد على المشركين، وسرد قصص الأنبياء، لأن الخطاب كان موجهاً لمجتمع لم يؤمن بعد.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'من هو الصحابي الذي أشار على أبي بكر الصديق بجمع القرآن في مصحف واحد بعد موقعة اليمامة؟', '["عمر بن الخطاب","زيد بن ثابت","علي بن أبي طالب","عثمان بن عفان"]'::jsonb, 0, 20, 3, 'multi', 'عمر بن الخطاب هو من أشار على أبي بكر الصديق بجمع القرآن بعد مقتل كثير من حفظة القرآن في موقعة اليمامة، خشية ضياع القرآن بوفاة الحفاظ.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'من أشرف على لجنة جمع القرآن وكتابته في عهد أبي بكر الصديق؟', '["أبي بن كعب","زيد بن ثابت","عبد الله بن مسعود","معاذ بن جبل"]'::jsonb, 1, 20, 4, 'multi', 'زيد بن ثابت الأنصاري هو الذي أشرف على جمع القرآن وكتابته في عهد أبي بكر، وقد اختير لحداثة سنّه وحضوره عرض القرآن الأخير على النبي صلى الله عليه وآله.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما الذي ميّز جمع عثمان بن عفان للقرآن عن جمع أبي بكر؟', '["ترتيب الآيات داخل السور","جمع القرآن لأول مرة من الألواح والصدور","توحيد المصاحف على حرف واحد وحرق ما سواها","إضافة التشكيل والنقط للمصحف"]'::jsonb, 2, 20, 5, 'multi', 'جمع عثمان كان الهدف منه توحيد المسلمين على مصحف واحد بلهجة قريش، وإرسال نسخ إلى الأمصار وحرق ما عداها من صحف ومصاحف مختلفة، لمنع الاختلاف في قراءة القرآن.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما السورة التي يُختلف في كونها مكية أم مدنية وأشهر الأقوال أنها مكية لكنها تضمنت آيات مدنية؟', '["سورة الحج","سورة الأعراف","سورة الأعلى","سورة البقرة"]'::jsonb, 0, 20, 6, 'multi', 'سورة الحج من السور التي اختُلف فيها اختلافاً واسعاً، فبعضها يُعدّ مكياً وبعضها مدنياً، وقال بعض العلماء إنها نزلت في الطريق بين مكة والمدينة، وهي نموذج على السور المختلطة.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما الضابط الذي ذكره العلماء لمعرفة الآية المكية داخل السورة المدنية؟', '["كل آية تتحدث عن الصلاة فهي مكية","كل آية تتحدث عن الجهاد فهي مدنية","كل آية تذكر المنافقين فهي مكية","كل آية تبدأ بـ ''يا أيها الناس'' فهي مكية"]'::jsonb, 3, 20, 7, 'multi', 'من الضوابط الاستقرائية المشهورة عند العلماء أن خطاب ''يا أيها الناس'' يغلب في السور المكية لأنه خطاب عام، بينما ''يا أيها الذين آمنوا'' يغلب في السور المدنية لأنه خطاب للمؤمنين المجتمعين.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما عدد السور المكية تقريباً من إجمالي سور القرآن الكريم البالغة 114 سورة؟', '["نحو 100 سورة","نحو 50 سورة","نحو 82 سورة","نحو 30 سورة"]'::jsonb, 2, 20, 8, 'multi', 'يُقدّر جمهور العلماء عدد السور المكية بنحو 82 إلى 86 سورة، والمدنية بنحو 28 إلى 30 سورة، وبعضها مختلف فيه، مما يدل على أن الجزء الأكبر من القرآن نزل قبل الهجرة.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_15, 'ما الموقف الذي يذهب إليه كثير من علماء الإمامية بشأن جمع القرآن وترتيبه؟', '["أن الإمام علياً جمع القرآن مرتباً حسب النزول بعد وفاة النبي مباشرة","أن القرآن لم يُجمع في عهد النبي قط","أن ترتيب الآيات اجتهادي لا توقيفي","أن القرآن جُمع في عهد أبي بكر فقط ولا حاجة لجمع عثمان"]'::jsonb, 0, 20, 9, 'multi', 'يذهب كثير من علماء الإمامية إلى أن الإمام علياً عليه السلام جمع القرآن بعد وفاة النبي مرتباً حسب النزول وفق ما أوصى به النبي، وأنه حمله على ناقته وعرضه على الصحابة فلم يقبلوه، وأودعه لمن بعده من الأئمة.', 'علوم القرآن');
END $$;

DO $$
DECLARE
  v_quiz_id_16 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('الناسخ والمنسوخ والمحكم والمتشابه', 'إسلاميات', 'علوم القرآن', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_16;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما التعريف الاصطلاحي للناسخ في علوم القرآن عند علماء الإمامية؟', '["هو البيان الذي يخصّص العام","هو الآية التي تُفسّر آية أخرى غامضة","هو الدليل الشرعي الذي يرفع حكماً ثابتاً بدليل شرعي سابق","هو النص الذي يُقيّد المطلق"]'::jsonb, 2, 20, 0, 'multi', 'عرّف علماء الإمامية كالشيخ الطوسي في التبيان الناسخَ بأنه الدليل الشرعي الرافع لحكم ثابت بدليل شرعي متقدم، وهو تعريف يستوجب وجود حكم سابق وارتفاعه بالنص اللاحق.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما شرط النسخ الذي اشترطه الشيخ الطوسي في التبيان ليكون الرفع نسخاً حقيقياً؟', '["أن يكون الحكم المنسوخ مقيداً بزمن معيّن","أن يكون الحكم المنسوخ مؤبداً في ظاهره ثم ارتفع بدليل لاحق","أن يتأخر الناسخ عن المنسوخ بسنة كاملة","أن يكون الناسخ حديثاً نبوياً لا قرآناً"]'::jsonb, 1, 20, 1, 'multi', 'اشترط الشيخ الطوسي في التبيان أن يكون الحكم المنسوخ ظاهره الدوام والاستمرار، فإن كان مؤقتاً فانقضاؤه بانتهاء وقته ليس نسخاً بل إتمام لمدته.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما الموقف الإمامي من نسخ القرآن بالسنة الآحادية؟', '["لا يجوز نسخ القرآن بخبر الواحد لأن القطعي لا يُرفع بالظني","يجوز إن كان الراوي معصوماً فقط","يجوز ذلك إن صحّت سند الرواية","أجازه أكثر علماء الإمامية بلا قيد"]'::jsonb, 0, 20, 2, 'multi', 'ذهب محققو الإمامية كالسيد الخوئي في البيان إلى أن نسخ القرآن القطعي الدلالة بخبر الواحد الظني غير جائز، لأن القطعي لا يُرفع بالظني.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'كم آية حدّدها السيد الخوئي في كتابه البيان على أنها منسوخة تحديداً علمياً دقيقاً؟', '["عشر آيات","مئتان وأربع عشرة آية","لم يُثبت نسخاً في القرآن أصلاً","آية واحدة وهي آية المناجاة"]'::jsonb, 3, 20, 3, 'multi', 'أثبت السيد الخوئي في البيان بعد فحص دقيق أن معظم ما ادّعي نسخه ليس نسخاً حقيقياً، وأن ما يمكن قبوله بصورة محققة ضيّق جداً، وقد اعتمد آية المناجاة في سورة المجادلة نموذجاً للنسخ الصحيح.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما المراد بالمحكم في القرآن الكريم وفق تعريف الشيخ الطوسي في التبيان؟', '["هو الآية التي نزلت في مكة فقط","هو كل آية لم تُنسخ","هو ما استقلّ بمعناه وأحكمت دلالته فلا يحتاج إلى بيان خارجي","هو النص الذي أجمع المفسرون على معناه"]'::jsonb, 2, 20, 4, 'multi', 'عرّف الشيخ الطوسي في التبيان المحكم بأنه ما أُحكمت دلالته وكان واضح المعنى لا يحتمل التأويل المتعدد، وهو أم الكتاب الذي يُرجع إليه عند الاشتباه.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما المتشابه في القرآن عند العلامة الطباطبائي في الميزان؟', '["هو الآية التي تتعلق بالغيبيات فحسب","هو الآية التي تحتمل وجوهاً متعددة ولا تستقل بمعناها إلا بردّها إلى المحكم","هو النص الذي خالف العقل","هو كل آية نُسخت"]'::jsonb, 1, 20, 5, 'multi', 'ذهب العلامة الطباطبائي في الميزان إلى أن المتشابه هو ما يتشابه على الفهم ويحتاج إلى ردّه إلى المحكم الذي هو أم الكتاب لتحديد مراده، وهو ليس مبهماً مطلقاً بل يتضح بالرجوع إلى المحكمات.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'من الذي يعلم تأويل المتشابهات في القرآن وفق آية آل عمران السابعة كما يُفسّرها علماء الإمامية؟', '["الله تعالى والراسخون في العلم وهم الأنبياء والأئمة المعصومون","العلماء المجتهدون بالاجتهاد المطلق","الله تعالى وحده دون سواه","جميع المؤمنين الصادقين"]'::jsonb, 0, 20, 6, 'multi', 'فسّر علماء الإمامية كالشيخ الطوسي والطباطبائي الراسخين في العلم بأنهم النبي والأئمة المعصومون، وأن الواو في قوله تعالى ''والراسخون في العلم'' عاطفة لا استئنافية، فيكون الأئمة شركاء في علم التأويل.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما نوع النسخ الذي ذهب إليه جمهور علماء الإمامية في قضية نسخ التلاوة مع بقاء الحكم؟', '["اختلفوا فيه بين مُجيز ومانع مناصفة","قبلوه في آيات الرجم فقط","قبلوه إذا صحّت الرواية","رفضوه جملةً وتفصيلاً ولم يقبلوا نسخ التلاوة مع بقاء الحكم"]'::jsonb, 3, 20, 7, 'multi', 'رفض محققو الإمامية كالسيد الخوئي نسخ التلاوة رفضاً قاطعاً مستدلّين بحفظ القرآن المذكور في الآية الكريمة ''إنا نحن نزلنا الذكر وإنا له لحافظون''، فضلاً عن التواتر الذي تثبت به القرآنية.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما العلاقة بين المحكم والمتشابه في منهج الاستدلال الفقهي الإمامي؟', '["يُترك المتشابه ولا يُستدل به ولا يُفسَّر","المتشابهات مقدّمة على المحكمات لخصوصيتها","المحكمات هي الأصل والمرجع، وتُحمل المتشابهات عليها وتُفسَّر في ضوئها","المحكم والمتشابه متساويان في الحجية"]'::jsonb, 2, 20, 8, 'multi', 'أقرّ الفقهاء الإماميون قاعدة أن المحكمات أمّهات الكتاب ومرجعه، وأن المتشابهات تُردّ إليها وتُفسّر في ضوئها، وهذا منهج التفسير القرآني بالقرآن الذي أكده الأئمة عليهم السلام.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_16, 'ما الفرق الجوهري بين النسخ والتخصيص عند الأصوليين الإماميين كالمحقق الحلي؟', '["التخصيص خاص بالسنة والنسخ خاص بالقرآن","النسخ رفع لحكم ثابت بعد العمل به، والتخصيص بيان لإخراج بعض الأفراد من عموم الحكم ابتداءً","النسخ أعم من التخصيص مطلقاً","النسخ والتخصيص مترادفان في الاصطلاح الأصولي"]'::jsonb, 1, 20, 9, 'multi', 'فرّق الأصوليون الإماميون كالمحقق الحلي في المعارج بين النسخ والتخصيص، فالنسخ رفع للحكم بعد استقراره والعمل به، أما التخصيص فهو كشف منذ البداية عن أن العام لم يُرَد به جميع الأفراد.', 'علوم القرآن');
END $$;

DO $$
DECLARE
  v_quiz_id_17 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('إعجاز القرآن والبلاغة والقصص القرآني', 'إسلاميات', 'علوم القرآن', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_17;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما المقصود بمصطلح ''الإعجاز البياني'' في القرآن الكريم؟', '["أن القرآن يحتوي على معلومات علمية مستقبلية فقط","عجز العرب وغيرهم عن الإتيان بمثله في بلاغته وفصاحته وأسلوبه","أن القرآن أُنزل بلغة لا يفهمها البشر","أن القرآن نُسخت تلاوته في بعض آياته"]'::jsonb, 1, 20, 0, 'multi', 'الإعجاز البياني يعني عجز الفصحاء والبلغاء عن الإتيان بمثل القرآن في نظمه وبيانه وأسلوبه، وهو أبرز وجوه إعجاز القرآن عند علماء الإمامية وغيرهم.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما التحدي الذي طرحه القرآن الكريم في سورة البقرة (الآية 23) للمشككين في نبوة النبي محمد صلى الله عليه وآله؟', '["الإتيان بعشر سور من مثله","الإتيان بآية واحدة مثله","الإتيان بكتاب كامل مثله","الإتيان بسورة واحدة من مثله"]'::jsonb, 3, 20, 1, 'multi', 'قال تعالى في سورة البقرة: ''فأتوا بسورة من مثله وادعوا شهداءكم من دون الله إن كنتم صادقين''، وهو تحدٍّ صريح بالإتيان بسورة واحدة.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما الوجه البلاغي الذي يُقصد به تعبير القرآن عن الأمر بصيغة الماضي للدلالة على تحقق الوقوع؟', '["التغليب","المجاز المرسل","صيغة الماضي للاستقبال أو التحقق","الالتفات"]'::jsonb, 2, 20, 2, 'multi', 'من أساليب القرآن البلاغية التعبير بصيغة الفعل الماضي عن الأمر المستقبلي للدلالة على تحقق وقوعه حتماً، وهو أسلوب راسخ في بلاغة العرب وقد بلغ ذروته في القرآن.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'أيٌّ من الأئمة الاثني عشر نُسب إليه تفسير بياني وعقدي مشهور للقرآن يُعرف بـ''تفسير الإمام العسكري''؟', '["الإمام علي بن أبي طالب عليه السلام","الإمام الحسن العسكري عليه السلام","الإمام محمد الباقر عليه السلام","الإمام جعفر الصادق عليه السلام"]'::jsonb, 1, 20, 3, 'multi', 'التفسير المنسوب إلى الإمام الحسن العسكري عليه السلام يتضمن بياناً لوجوه إعجاز القرآن وقصصه، وهو من المصادر التي يستشهد بها الباحثون في علوم القرآن الإمامية.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما القصة القرآنية التي خُصصت لها سورة كاملة تحمل اسم صاحبها وقد وصفها القرآن بأنها ''أحسن القصص''؟', '["قصة يوسف عليه السلام","قصة موسى عليه السلام","قصة إبراهيم عليه السلام","قصة عيسى عليه السلام"]'::jsonb, 0, 20, 4, 'multi', 'قال تعالى في مطلع سورة يوسف: ''نحن نقص عليك أحسن القصص''، وقد أجمع المفسرون على أن هذا الوصف يعود على قصة يوسف عليه السلام المذكورة في السورة.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما الظاهرة البلاغية التي يُعبّر فيها القرآن بضمير المتكلم المفرد تارةً وبضمير الجمع تارةً أخرى في سياق واحد وهي من علامات الأسلوب القرآني الرفيع؟', '["التضمين","الجناس","الالتفات","الاستعارة التصريحية"]'::jsonb, 2, 20, 5, 'multi', 'الالتفات هو الانتقال من ضمير إلى آخر أو من صيغة إلى أخرى في السياق الواحد، وهو أسلوب بلاغي رفيع أكثر منه القرآن الكريم ويُعدّ من وجوه إعجازه البياني.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما الذي يُميّز أسلوب القصص القرآني عن سائر القصص الأدبية وفق ما أكده العلماء المسلمون؟', '["اعتماده على الأسماء والتواريخ الدقيقة دائماً","توجيهه نحو الهداية والعبرة لا مجرد الترفيه وسرد الأحداث","اختصاره الشديد لدرجة إهمال التفاصيل كلها","اعتماده على الخيال والأسطورة لجذب القارئ"]'::jsonb, 1, 20, 6, 'multi', 'القصص القرآني يهدف أساساً إلى الهداية والعبرة والموعظة كما قال تعالى: ''لقد كان في قصصهم عبرة لأولي الألباب''، وليس غرضه الترفيه البحت أو السرد التاريخي المجرد.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما وجه الإعجاز في إخبار القرآن عن الغيب كقصة أصحاب الكهف وقصة ذي القرنين وغيرها؟', '["أن القرآن أخبر بأمور غيبية لم يكن في مقدور أحد معرفتها إلا بوحي إلهي","أن النبي صلى الله عليه وآله كان قد درس التوراة والإنجيل قبل النبوة","أن هذه القصص مأخوذة من الثقافة العربية الجاهلية","أن الصحابة رووها عن أهل الكتاب وأدرجوها في القرآن"]'::jsonb, 0, 20, 7, 'multi', 'إخبار القرآن عن أحداث غيبية سابقة ولاحقة يُعد من وجوه إعجازه، إذ كان النبي صلى الله عليه وآله أمياً ولم يتلق علماً من بشر، فكان ذلك دليلاً على الوحي الإلهي.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما المصطلح الذي يُطلق على علم دراسة أوجه إعجاز القرآن وبلاغته في التراث الإسلامي؟', '["علم الأصول","علم الكلام","علم الحديث","علم إعجاز القرآن أو علم البيان القرآني"]'::jsonb, 3, 20, 8, 'multi', 'علم إعجاز القرآن أو ما يُسمى أحياناً علم البيان القرآني يختص بدراسة الأوجه التي عجز فيها البشر عن مجاراة القرآن، وهو فرع من فروع علوم القرآن.', 'علوم القرآن');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_17, 'ما الموقف الذي يُعبّر عنه مصطلح ''الصرفة'' في سياق الإعجاز القرآني؟', '["القول بأن العرب عارضوا القرآن فعلاً ولكنهم أخفوا ذلك","القول بأن القرآن أُنزل بلغة مصطنعة غير عربية","القول بأن الله صرف العرب عن التحدي بسلب قدرتهم على المعارضة لا لأن القرآن في ذاته معجز","القول بأن الإعجاز يقتصر على الإخبار بالغيب فقط"]'::jsonb, 2, 20, 9, 'multi', 'القائلون بالصرفة كالنظّام وبعض المعتزلة يرون أن الله صرف العرب عن معارضة القرآن بسلب قدرتهم، لا أن القرآن في ذاته فاق قدرتهم، وقد رد عليهم جمهور العلماء بأن الإعجاز في ذات القرآن وبيانه.', 'علوم القرآن');
END $$;

DO $$
DECLARE
  v_quiz_id_18 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('آية التطهير والمودة وأسباب نزولها', 'إسلاميات', 'آيات مرتبطة بأهل البيت', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_18;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_18, 'ما هو نص آية التطهير الواردة في القرآن الكريم والمتعلقة بأهل البيت؟', '["قل لا أسألكم عليه أجرا إلا المودة في القربى","والذين آمنوا واتبعتهم ذريتهم بإيمان","إنما يريد الله ليذهب عنكم الرجس أهل البيت ويطهركم تطهيرا","إن الله اصطفى آدم ونوحا وآل إبراهيم وآل عمران"]'::jsonb, 2, 20, 0, 'multi', 'آية التطهير هي قوله تعالى في سورة الأحزاب الآية 33: ''إنما يريد الله ليذهب عنكم الرجس أهل البيت ويطهركم تطهيرا''، وهي من أبرز الآيات الدالة على مقام أهل البيت.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_18, 'في أي سورة وردت آية التطهير؟', '["سورة الأحزاب","سورة النساء","سورة آل عمران","سورة الشورى"]'::jsonb, 0, 20, 1, 'multi', 'وردت آية التطهير في سورة الأحزاب الآية 33، وقد تضمنت إرادة الله تعالى تطهير أهل البيت النبوي من كل رجس.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_18, 'من المقصود بأهل البيت في آية التطهير وفق روايات الفريقين المعتمدة؟', '["بنو هاشم جميعهم","النبي وعلي وفاطمة والحسن والحسين","جميع نساء النبي فقط","الصحابة الأربعة الخلفاء"]'::jsonb, 1, 20, 2, 'multi', 'أجمعت روايات الفريقين على أن المقصود بأهل البيت في الآية هم أصحاب الكساء: النبي محمد وعلي وفاطمة والحسن والحسين، وقد وردت روايات كساء مفصلة في مصادر عديدة منها صحيح مسلم وتفسير الطبري.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_18, 'ما سبب نزول آية التطهير المشهور في كتب التفسير والحديث؟', '["نزلت في حجة الوداع خطبة النبي","نزلت في غزوة بدر لتمييز المؤمنين","نزلت في شأن أزواج النبي بعد حادثة الإفك","نزلت حين جمع النبي عليا وفاطمة والحسنين تحت كساء"]'::jsonb, 3, 20, 3, 'multi', 'المشهور في كتب التفسير والحديث أن الآية نزلت حين جمع النبي صلى الله عليه وآله عليا وفاطمة والحسن والحسين تحت كساء وقال: ''اللهم هؤلاء أهل بيتي فأذهب عنهم الرجس وطهرهم تطهيرا''، وهو حديث الكساء المروي في المصادر السنية والشيعية.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_18, 'في أي سورة وردت آية المودة ''قل لا أسألكم عليه أجرا إلا المودة في القربى''؟', '["سورة الشورى","سورة الأنفال","سورة الأحزاب","سورة البقرة"]'::jsonb, 0, 20, 4, 'multi', 'وردت آية المودة في سورة الشورى الآية 23، قال تعالى: ''قل لا أسألكم عليه أجرا إلا المودة في القربى''، وهي تدل على وجوب مودة قربى النبي.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_18, 'من المقصود بـ''القربى'' في آية المودة وفق الرأي الإمامي المعتمد؟', '["الأنصار والمهاجرون","علي وفاطمة وذريتهما","جميع قريش","بنو أمية وبنو العباس"]'::jsonb, 1, 20, 5, 'multi', 'يرى الإماميون أن المقصود بالقربى في الآية هم علي وفاطمة وذريتهما الأئمة، وقد روي ذلك عن ابن عباس أيضا، وأكد الطبرسي في مجمع البيان هذا المعنى نقلا عن أئمة أهل البيت.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_18, 'ما الدلالة العقدية التي يستنتجها الإماميون من قوله تعالى في آية التطهير ''إنما يريد الله''؟', '["أن الإرادة خاصة بنساء النبي في بيوتهن","أن الإرادة مشروطة بأفعال أهل البيت أنفسهم","أن الإرادة تشريعية تعني الأمر بالتطهير","أن الإرادة تكوينية تعني العصمة والطهارة المطلقة لأهل البيت"]'::jsonb, 3, 20, 6, 'multi', 'يستدل الإماميون بكلمة ''إنما'' الدالة على الحصر وبأداة ''يريد'' الدالة على الإرادة التكوينية لا التشريعية على ثبوت العصمة لأهل البيت، وقد فصّل ذلك الشيخ المفيد والسيد المرتضى في مؤلفاتهما العقدية.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_18, 'ما موقف الإمامية من الجمع بين آية التطهير وآية المودة في إثبات مكانة الأئمة؟', '["يستدلون بهما معا على وجوب طاعة أهل البيت ومودتهم لكونهم مطهرين ومفترضي الطاعة","يرون أنهما آيتان منفصلتان لا علاقة بينهما","يعتبرون آية المودة منسوخة بآية التطهير","يرون أن آية المودة خاصة بالجانب المالي فقط"]'::jsonb, 0, 20, 7, 'multi', 'يجمع علماء الإمامية بين الآيتين للاستدلال على منزلة أهل البيت، فآية التطهير تثبت طهارتهم وعصمتهم، وآية المودة تجعل مودتهم واجبة فريضة، مما يدل على وجوب اتباعهم، وهو ما أكده العلامة الحلي في كشف المراد.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_18, 'ما الرواية التي أوردها الثعلبي في تفسيره عن ابن عباس بشأن سبب نزول آية المودة؟', '["أن النبي طلب من الصحابة إنفاق المال في سبيل الله فنزلت","أن قريشا طلبت من النبي مالا فنزلت","أن الأنصار سألوا النبي إن كانوا مأجورين على نصرته فنزلت","أن المنافقين اتهموا النبي بطلب الأجر فنزلت لدفع تهمتهم"]'::jsonb, 2, 20, 8, 'multi', 'روى الثعلبي في تفسيره الكشف والبيان عن ابن عباس أن الأنصار قالوا للنبي إنهم يريدون الإنفاق عليه، فنزلت الآية لتبين أن أجره هو مودة القربى لا المال، وهذا يؤكد ارتباط الآية بأهل البيت النبوي.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_18, 'ما الفرق الذي يذكره علماء الإمامية بين مفهوم ''أهل البيت'' في الآية 33 من الأحزاب ومفهوم ''أزواج النبي'' في الآيات السابقة واللاحقة لها؟', '["أزواج النبي هن المقصودات في آية التطهير دون سواهن","الآيات كلها في شأن بنات النبي الأربع","لا فرق بينهما والمقصود واحد","آية التطهير جملة معترضة خُصّ بها أصحاب الكساء بدليل انتقال الضمير من المؤنث إلى المذكر"]'::jsonb, 3, 20, 9, 'multi', 'يستدل علماء الإمامية كالشيخ الطوسي في التبيان على أن آية التطهير جملة اعتراضية مستقلة تخص أصحاب الكساء، والدليل اللغوي هو تحول ضمير الخطاب من المؤنث الجمع الموجه لأزواج النبي إلى المذكر الجمع في ''عنكم'' و''يطهركم''، مما يدل على تغيير المخاطَب.', 'آيات مرتبطة بأهل البيت');
END $$;

DO $$
DECLARE
  v_quiz_id_19 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('آية المباهلة ودلالاتها العقائدية والتاريخية', 'إسلاميات', 'آيات مرتبطة بأهل البيت', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_19;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_19, 'ما هو رقم آية المباهلة في القرآن الكريم وفي أي سورة وردت؟', '["سورة البقرة الآية 124","سورة آل عمران الآية 61","سورة المائدة الآية 67","سورة النساء الآية 59"]'::jsonb, 1, 20, 0, 'multi', 'آية المباهلة هي الآية 61 من سورة آل عمران وتقول: ''فمن حاجك فيه من بعد ما جاءك من العلم فقل تعالوا ندع أبناءنا وأبناءكم ونساءنا ونساءكم وأنفسنا وأنفسكم ثم نبتهل فنجعل لعنة الله على الكاذبين''.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_19, 'من هم الذين خرج معهم النبي صلى الله عليه وآله في حادثة المباهلة وفق الروايات المتواترة عند الفريقين؟', '["أبو بكر وعمر وعثمان وعلي","عقيل بن أبي طالب وجعفر وعلي وفاطمة","الإمام علي وخديجة وعبد الله بن مسعود","الإمام علي والسيدة فاطمة والإمامان الحسن والحسين"]'::jsonb, 3, 20, 1, 'multi', 'اتفق المفسرون من الفريقين على أن النبي خرج بالإمام علي والسيدة فاطمة والحسن والحسين عليهم السلام، وهو ما رواه مسلم في صحيحه وكثير من المفسرين كالطبري والزمخشري.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_19, 'ما الدلالة العقائدية الإمامية المستفادة من تعبير ''أنفسنا'' في آية المباهلة؟', '["أن الإمام علياً هو نفس النبي ومساوٍ له في المنزلة ما عدا النبوة","أن المقصود بأنفسنا عموم المسلمين","أن الآية تدل على أفضلية أبي بكر لأنه لم يُدعَ للمباهلة","أن النبي كان وحيداً في المباهلة دون أصحابه"]'::jsonb, 0, 20, 2, 'multi', 'يستدل علماء الإمامية بتعبير ''أنفسنا'' على أن الإمام علياً هو نفس النبي بمعنى المساواة في المنزلة الروحية والمقام الإلهي ما عدا خصوصية النبوة، وهو استدلال يذكره الشيخ المفيد والطوسي وغيرهما.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_19, 'مع أي وفد نصراني جرت حادثة المباهلة التاريخية؟', '["وفد اليمن","وفد نجران","وفد أنطاكية","وفد الحبشة"]'::jsonb, 1, 20, 3, 'multi', 'جرت المباهلة مع وفد نصارى نجران الذين قدموا إلى المدينة المنورة للتفاوض مع النبي حول قضية عيسى عليه السلام، وقد رفضوا المباهلة في النهاية وطلبوا المصالحة.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_19, 'ما السبب الذي دفع وفد نجران إلى التراجع عن المباهلة وفق الروايات التاريخية؟', '["رفض قائدهم المشاركة لمرضه","تدخل ملك الروم ونهيه عن المباهلة","خوفهم مما رأوه من نور وهيبة النبي وأهل بيته","إسلام رئيس الوفد في اللحظة الأخيرة"]'::jsonb, 2, 20, 4, 'multi', 'تذكر الروايات أن أسقف نجران ورجاله لما رأوا النبي خارجاً بأهل بيته بتلك الهيئة النورانية أدركوا صدق نبوته وخشوا الهلاك إن باهلوه فآثروا الصلح.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_19, 'ماذا يُسمى الحدث السنوي الذي يُحيي فيه الشيعة الإمامية ذكرى آية المباهلة؟', '["يوم المباهلة وهو الرابع والعشرون من ذي الحجة","يوم الجمعة الكبرى","يوم عاشوراء","يوم الغدير وهو الثامن عشر من ذي الحجة"]'::jsonb, 0, 20, 5, 'multi', 'يحتفل الشيعة الإمامية بيوم المباهلة في الرابع والعشرين من ذي الحجة، ويُعدّ من المناسبات الدينية المهمة التي تُؤكد مكانة أهل البيت عليهم السلام.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_19, 'كيف يستدل علماء الإمامية بآية المباهلة على مسألة الإمامة تحديداً؟', '["أن المقصود بالآية عموم المؤمنين لا أهل البيت خصوصاً","أن الآية دليل على أفضلية الهجرة على النسب","أن الآية تدل على وجوب الشورى في تعيين الإمام","أن تخصيص النبي لأهل بيته دون سائر الصحابة يدل على مكانتهم الخاصة واستحقاقهم للإمامة"]'::jsonb, 3, 20, 6, 'multi', 'يرى علماء الإمامية كالشيخ المفيد في ''الفصول المختارة'' وابن المطهر الحلي في ''منهاج الكرامة'' أن اختيار النبي لعلي وفاطمة والحسن والحسين دون غيرهم من الصحابة دليل قاطع على أفضليتهم وأحقيتهم بالإمامة.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_19, 'من المفسرين السنة الذين أقروا بأن المقصود بـ''أبناءنا'' في آية المباهلة هما الحسن والحسين؟', '["ابن تيمية وابن كثير والسيوطي","الفخر الرازي والزمخشري والطبري","الآلوسي والبغوي وابن الجوزي","ابن حزم والقرطبي والشوكاني"]'::jsonb, 1, 20, 7, 'multi', 'أقر الفخر الرازي في ''مفاتيح الغيب'' والزمخشري في ''الكشاف'' والطبري في ''جامع البيان'' بأن النبي أحضر الحسن والحسين عند المباهلة وهما المقصودان بـ''أبناءنا''.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_19, 'ما الذي يستدل به الإمامية من كون السيدة فاطمة هي المقصودة بـ''نساءنا'' في آية المباهلة؟', '["أنها سيدة نساء العالمين ومكانتها تفوق سائر النساء ما يجعلها الأجدر بالتمثيل في أعظم مباهلة","أن المباهلة كانت قبل هجرة أمهات المؤمنين","أن النساء الأخريات رفضن المشاركة","أن النبي لم يكن متزوجاً حين المباهلة"]'::jsonb, 0, 20, 8, 'multi', 'يستدل علماء الإمامية بهذا الاختيار على أن السيدة فاطمة عليها السلام هي سيدة نساء العالمين وأفضلهن، وأن النبي اختارها تحديداً لتكون الممثلة لنساء الأمة في هذا الموقف الخطير.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_19, 'ما الصلة بين آية المباهلة وآية التطهير في الاستدلال الإمامي على عصمة أهل البيت؟', '["الآيتان نزلتا في سياق الحديث عن نساء النبي حصراً","آية التطهير نزلت بعد المباهلة بزمن طويل ولا صلة بينهما","كلتا الآيتين تخصان الأشخاص الخمسة أصحاب الكساء مما يؤكد مكانتهم الخاصة وعصمتهم","آية المباهلة تشمل عموم الصحابة وآية التطهير تخص أهل البيت فقط"]'::jsonb, 2, 20, 9, 'multi', 'يرى علماء الإمامية كالعلامة الطباطبائي في ''الميزان'' أن كلتا الآيتين تتعلقان بأصحاب الكساء الخمسة، فآية التطهير أثبتت عصمتهم وآية المباهلة أثبتت مكانتهم التي لا يوازيها أحد، مما يعزز الدليل على عصمتهم واستحقاقهم للإمامة.', 'آيات مرتبطة بأهل البيت');
END $$;

DO $$
DECLARE
  v_quiz_id_20 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('آية الغدير والولاية وإكمال الدين', 'إسلاميات', 'آيات مرتبطة بأهل البيت', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_20;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_20, 'ما هو النص الكامل لآية الغدير التي تأمر النبي بتبليغ الرسالة المتعلقة بالولاية؟', '["يا أيها النبي جاهد الكفار والمنافقين واغلظ عليهم","يا أيها الرسول بلغ ما أنزل إليك من ربك وإن لم تفعل فما بلغت رسالته","يا أيها الرسول لا يحزنك الذين يسارعون في الكفر","يا أيها الذين آمنوا أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم"]'::jsonb, 1, 20, 0, 'multi', 'هي الآية 67 من سورة المائدة وتُعرف بآية التبليغ أو آية الغدير وقد نزلت بحسب الروايات الشيعية بشأن تبليغ ولاية علي بن أبي طالب.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_20, 'في أي سورة وردت آية إكمال الدين ''اليوم أكملت لكم دينكم وأتممت عليكم نعمتي ورضيت لكم الإسلام دينا''؟', '["سورة البقرة","سورة آل عمران","سورة النساء","سورة المائدة"]'::jsonb, 3, 20, 1, 'multi', 'وردت هذه الآية في سورة المائدة الآية الثالثة ويرى علماء الإمامية أنها نزلت عقب إعلان ولاية الإمام علي يوم غدير خم.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_20, 'ما اليوم الذي يُحدده علماء الإمامية موعداً لنزول آية إكمال الدين وإعلان ولاية الإمام علي؟', '["يوم فتح مكة","يوم عرفة في الحج الأخير","يوم الثامن عشر من ذي الحجة في غدير خم","يوم نزول سورة البراءة"]'::jsonb, 2, 20, 2, 'multi', 'يُجمع علماء الإمامية على أن النبي أعلن ولاية علي في غدير خم في الثامن عشر من ذي الحجة عام حجة الوداع وعندها نزلت آية إكمال الدين.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_20, 'ما الآية القرآنية التي يستدل بها الإمامية على ركنية الولاية في الدين وأن تركها يُعطّل الرسالة؟', '["آية المودة ''قل لا أسألكم عليه أجرا إلا المودة في القربى''","آية التبليغ ''يا أيها الرسول بلغ ما أنزل إليك من ربك''","آية الولاية ''إنما وليكم الله ورسوله والذين آمنوا''","آية الإطاعة ''أطيعوا الله وأطيعوا الرسول''"]'::jsonb, 1, 20, 3, 'multi', 'يستدل الإمامية بآية التبليغ في المائدة 67 على أن إبلاغ ولاية علي كان فريضة ركنية بحيث إن تركها يعني ترك الرسالة كلها وهو دليل على مركزية الولاية في الدين.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_20, 'ما تفسير الشيخ الطوسي في التبيان لقوله تعالى ''إنما وليكم الله ورسوله والذين آمنوا الذين يقيمون الصلاة ويؤتون الزكاة وهم راكعون''؟', '["إنها نزلت في أبي بكر وعمر","إنها تعني أهل الحل والعقد من الصحابة","إنها نزلت في المؤمنين عموماً دون تخصيص","إنها نزلت في علي بن أبي طالب حين تصدّق بخاتمه في الصلاة"]'::jsonb, 3, 20, 4, 'multi', 'ذكر الشيخ الطوسي في تفسير التبيان أن الآية الخامسة والخمسين من المائدة نزلت في علي بن أبي طالب حين تصدّق بخاتمه على السائل وهو راكع في الصلاة وهو تفسير إجماعي عند الإمامية.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_20, 'ما دلالة جملة ''وإن لم تفعل فما بلغت رسالته'' في آية التبليغ عند المفسرين الشيعة؟', '["تعني أن الرسالة ناقصة ما لم يُبلَّغ أمر الولاية","تعني أن النبي كان مقصّرا في التبليغ","تعني أن الرسالة مرتبطة بالتشريعات المالية فقط","تعني أن الدين يكتمل بالجهاد فقط"]'::jsonb, 0, 20, 5, 'multi', 'يرى مفسرو الإمامية كالطبرسي في مجمع البيان أن هذه الجملة تدل دلالة قاطعة على أن إبلاغ أمر الولاية يساوي في أهميته مجموع الرسالة فلو أُغفل لانتفت الرسالة كلها.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_20, 'أي كتاب تفسيري شيعي كلاسيكي خصص بحثاً مفصلاً لآيات الغدير وأثبت نزولها في ولاية علي عليه السلام؟', '["تفسير القمي فقط","مجمع البيان للطبرسي والتبيان للطوسي","تفسير الصافي للفيض الكاشاني فقط","تفسير العياشي فقط"]'::jsonb, 1, 20, 6, 'multi', 'كلٌّ من مجمع البيان للشيخ الطبرسي والتبيان للشيخ الطوسي أفردا بحوثاً مستفيضة لآيات الغدير والولاية ووثّقا رواياتها وأسباب نزولها في علي بن أبي طالب.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_20, 'ما العلاقة التي يُقيمها علماء الإمامية بين آية التبليغ وآية إكمال الدين من حيث الترتيب والمضمون؟', '["آية التبليغ نزلت بعد إكمال الدين لتأكيد ما جرى","الآيتان مستقلتان تماماً ولا علاقة بينهما","آية التبليغ أمرٌ قبلي بالإعلان عن الولاية وآية إكمال الدين نزلت بعده تأكيداً للإنجاز","آية إكمال الدين تتعلق بالتشريعات الفقهية فقط لا بالولاية"]'::jsonb, 2, 20, 7, 'multi', 'يرى علماء الإمامية كالعلامة الطباطبائي في الميزان أن آية التبليغ جاءت أمراً إلهياً مسبقاً بالإعلان عن الولاية فلما أعلن النبي ذلك في غدير خم نزلت آية إكمال الدين تتويجاً لهذا الإعلان.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_20, 'ما الذي يُستنبط من عبارة ''والله يعصمك من الناس'' في آية التبليغ وفق التفسير الإمامي؟', '["أن النبي كان يتردد في إعلان ولاية علي خشية ردود فعل بعض الصحابة فوعده الله بالعصمة","أن النبي كان يخشى على نفسه من الكفار عند إعلان التوحيد","أن العصمة تعني العصمة من الذنوب والمعاصي","أن الآية تتعلق بحماية النبي في المعارك الحربية"]'::jsonb, 0, 20, 8, 'multi', 'يُفسّر علماء الإمامية كالشيخ المفيد وصاحب الميزان العبارة بأن النبي كان يتحاشى إعلان الولاية مخافة ردود الفعل فجاء الوعد الإلهي بالعصمة تطميناً له على إبلاغ هذا الأمر الخطير.', 'آيات مرتبطة بأهل البيت');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_20, 'ما آية المودة التي يربطها الإمامية بمنزلة أهل البيت وتكملة آيات الولاية؟', '["واعلموا أنما غنمتم من شيء - الأنفال 41","وآت ذا القربى حقه - الإسراء 26","إنما يريد الله ليذهب عنكم الرجس أهل البيت - الأحزاب 33","قل لا أسألكم عليه أجرا إلا المودة في القربى - الشورى 23"]'::jsonb, 3, 20, 9, 'multi', 'آية المودة هي الآية الثالثة والعشرون من سورة الشورى ويستدل بها الإمامية على وجوب مودة أهل البيت باعتبارها أجر الرسالة وتكملة للمنظومة الولائية إلى جانب آيات الغدير وإكمال الدين.', 'آيات مرتبطة بأهل البيت');
END $$;

DO $$
DECLARE
  v_quiz_id_21 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('نشأة المذهب الجعفري وتاريخ الفقه الشيعي', 'إسلاميات', 'تاريخ التشيع والفرق', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_21;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_21, 'ما هو الاسم الكامل للإمام الذي يُنسب إليه المذهب الجعفري؟', '["جعفر بن الحسن العسكري","جعفر بن موسى الكاظم","جعفر بن علي الهادي","جعفر بن محمد الصادق"]'::jsonb, 3, 20, 0, 'multi', 'المذهب الجعفري منسوب إلى الإمام جعفر بن محمد الصادق، سادس أئمة الشيعة الاثني عشرية، الذي عاش بين عامَي 80 و148 للهجرة.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_21, 'في أي قرن هجري بلغ الفقه الجعفري ذروة تدوينه وازدهاره على يد الإمام الصادق؟', '["القرن الثاني الهجري","القرن الثالث الهجري","القرن الأول الهجري","القرن الرابع الهجري"]'::jsonb, 0, 20, 1, 'multi', 'ازدهر الفقه الجعفري وتدوينه في القرن الثاني الهجري، إذ استغل الإمام الصادق حالة الضعف السياسي بين الدولتين الأموية والعباسية لتأسيس حلقات علمية واسعة.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_21, 'ما المصطلح الذي يُطلق على مجموعة الروايات الفقهية والحديثية التي دوّنها تلاميذ الإمام الصادق وتُعدّ أساس الفقه الجعفري؟', '["موطأ الشيعة","الأصول الأربعمئة","الكتب الأربعة","مسند الإمامية"]'::jsonb, 1, 20, 2, 'multi', 'يُطلق على هذه المجموعة اسم ''الأصول الأربعمئة''، وهي مجاميع حديثية دوّنها أصحاب الإمام الصادق مباشرةً من رواياته، وشكّلت المصدر الأوّلي للفقه الجعفري.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_21, 'أيّ من الفِرَق التالية تعدّ من أبرز الفرق الشيعية التي انشقّت عن الخط الإمامي الاثني عشري بعد وفاة الإمام جعفر الصادق؟', '["الزيدية","العلوية","الإسماعيلية","الكيسانية"]'::jsonb, 2, 20, 3, 'multi', 'الإسماعيلية هي الفرقة التي انشقّت عن الخط الإمامي الاثني عشري إثر وفاة إسماعيل بن جعفر في حياة أبيه، إذ رأى أتباعها أن الإمامة توقّفت فيه أو انتقلت إلى ابنه محمد بن إسماعيل.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_21, 'ما الحدث التاريخي الذي يُعتبر المنطلق الأول لنشأة التشيع وفق المصادر الإمامية؟', '["ثورة التوابين سنة 65 هـ","واقعة كربلاء سنة 61 هـ","معركة صفين سنة 37 هـ","واقعة الغدير يوم 18 ذي الحجة سنة 10 هـ"]'::jsonb, 3, 20, 4, 'multi', 'تعدّ المصادر الإمامية واقعةَ غدير خم، حين أعلن النبي ولاية علي بن أبي طالب، المنطلقَ الأول لنشأة التشيع، وتعتبرها دليلاً نصّياً على الإمامة.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_21, 'مَن هو العالم الشيعي الذي يُعدّ مؤسس المدرسة الفقهية العقلية الإمامية في القرن الرابع الهجري وصاحب كتاب ''المقنعة''؟', '["الشيخ المفيد","ابن أبي عقيل","الشيخ الطوسي","الشيخ الكليني"]'::jsonb, 0, 20, 5, 'multi', 'الشيخ المفيد (336-413هـ) هو مؤسس المدرسة الفقهية العقلية الإمامية، وكتابه ''المقنعة'' من أوائل المتون الفقهية المنظّمة في الفقه الجعفري، وقد أدخل علم الكلام في خدمة العقيدة الإمامية.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_21, 'ما اسم الكتاب الحديثي الذي ألّفه الشيخ الكليني ويُعدّ أهم المصادر الروائية في الفقه الجعفري؟', '["تهذيب الأحكام","الاستبصار","الكافي","من لا يحضره الفقيه"]'::jsonb, 2, 20, 6, 'multi', 'كتاب ''الكافي'' للشيخ محمد بن يعقوب الكليني (ت 329هـ) هو أشمل الكتب الأربعة الحديثية الإمامية وأقدمها، ويحتوي على آلاف الروايات في العقيدة والفقه والأخلاق.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_21, 'ما التسمية التي أطلقها الشيعة الإمامية على مرحلة غياب الإمام الثاني عشر المهدي عن الأنظار منذ سنة 260 هـ؟', '["عصر الانتظار الكبير","عصر الحيرة","زمن الفترة","الغيبة الصغرى ثم الغيبة الكبرى"]'::jsonb, 3, 20, 7, 'multi', 'قسّم الشيعة الإمامية غياب الإمام المهدي إلى مرحلتين: الغيبة الصغرى (260-329هـ) حين كان يتواصل عبر سفراء أربعة، ثم الغيبة الكبرى التي امتدت إلى يومنا هذا.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_21, 'أيّ المدن الإسلامية شكّلت المركز الأكاديمي الأبرز للدراسات الفقهية الإمامية في القرن الرابع والخامس الهجريين؟', '["بغداد","قم المقدسة","المدينة المنورة","الكوفة"]'::jsonb, 0, 20, 8, 'multi', 'احتلّت بغداد مكانةً محورية في القرن الرابع والخامس الهجريين، إذ كانت موطن علماء بارزين كالشيخ المفيد والسيد المرتضى والشيخ الطوسي، قبل أن تنتقل الزعامة العلمية إلى النجف.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_21, 'ما المصطلح الفقهي الذي استحدثه الشيخ الطوسي وأدخله في منهج الفقه الجعفري لاستنباط الأحكام عند غياب النص الصريح؟', '["القياس الجلي","الاجتهاد المنظّم بالعقل","سدّ الذرائع","الاستصحاب الموسّع"]'::jsonb, 1, 20, 9, 'multi', 'وسّع الشيخ الطوسي (385-460هـ) منهج الاجتهاد العقلي في الفقه الجعفري من خلال كتبه كـ''المبسوط'' و''الخلاف''، محوّلاً الفقه الإمامي من الاقتصار على النص إلى استخدام العقل والأصول الفقهية المنظّمة.', 'تاريخ التشيع والفرق');
END $$;

DO $$
DECLARE
  v_quiz_id_22 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('علماء ومراجع كبار (الشيخ الطوسي، الحلي، الخوئي)', 'إسلاميات', 'تاريخ التشيع والفرق', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_22;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_22, 'ما اللقب الذي اشتُهر به الشيخ محمد بن الحسن الطوسي في التراث الشيعي؟', '["علامة الحلة","المحقق الأول","شيخ الطائفة","السيد المرتضى"]'::jsonb, 2, 20, 0, 'multi', 'اشتُهر الشيخ محمد بن الحسن الطوسي بلقب ''شيخ الطائفة'' لمكانته العلمية الرفيعة وزعامته للمذهب الإمامي في القرن الخامس الهجري.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_22, 'في أي مدينة استقر الشيخ الطوسي بعد إحراق داره في بغداد وأسس فيها مدرسة علمية كبرى؟', '["الحلة","النجف الأشرف","كربلاء","قم المقدسة"]'::jsonb, 1, 20, 1, 'multi', 'بعد إحراق داره ومكتبته في بغداد عام 448هـ على يد الغوغاء، هاجر الشيخ الطوسي إلى النجف الأشرف وأسس فيها الحوزة العلمية التي غدت مركزاً للدراسات الشيعية.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_22, 'ما اسم الكتاب الذي ألّفه الشيخ الطوسي في علم الرجال والذي يُعدّ من أهم مصادر علم الرجال الإمامي؟', '["الفهرست","الكافي","الاستبصار","من لا يحضره الفقيه"]'::jsonb, 0, 20, 2, 'multi', 'كتاب ''الفهرست'' للشيخ الطوسي يُعدّ من أمهات كتب علم الرجال الإمامي، إذ أحصى فيه أسماء مصنفي الشيعة ومؤلفاتهم.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_22, 'بأي لقب عُرف الحسن بن يوسف بن المطهر الحلي في الأوساط العلمية الشيعية؟', '["الشهيد الأول","المحقق الثاني","شيخ الطائفة","العلامة الحلي"]'::jsonb, 3, 20, 3, 'multi', 'اشتُهر الحسن بن يوسف بن المطهر الحلي بلقب ''العلامة الحلي'' تقديراً لسعة علمه في الفقه والكلام والأصول، وهو من أبرز علماء الإمامية في القرن السابع والثامن الهجريين.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_22, 'أيٌّ من الكتب الآتية يُنسب إلى العلامة الحلي في علم الكلام والعقيدة الإمامية؟', '["بحار الأنوار","تهذيب الأحكام","كشف المراد في شرح تجريد الاعتقاد","وسائل الشيعة"]'::jsonb, 2, 20, 4, 'multi', 'كتاب ''كشف المراد في شرح تجريد الاعتقاد'' للعلامة الحلي هو شرح على تجريد الاعتقاد للمحقق نصير الدين الطوسي، ويُعدّ مرجعاً أساسياً في علم الكلام الإمامي.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_22, 'ما الدور العقدي المهم الذي أدّاه العلامة الحلي في بلاط السلطان المغولي أولجايتو؟', '["تأسيس حوزة علمية في تبريز","إقناعه باعتناق المذهب الإمامي الاثني عشري","تدوين دستور ديني للدولة الإيلخانية","إعلان الجهاد ضد الصليبيين"]'::jsonb, 1, 20, 5, 'multi', 'أدّى العلامة الحلي دوراً محورياً في إقناع السلطان المغولي أولجايتو خدابنده باعتناق المذهب الإمامي الاثني عشري، مما أسهم في انتشار التشيع في إيران وآسيا الوسطى.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_22, 'في أي مدينة وُلد السيد أبو القاسم الموسوي الخوئي الذي غدا من أبرز مراجع التقليد في القرن العشرين؟', '["خوي في إيران","مشهد","كربلاء","النجف الأشرف"]'::jsonb, 0, 20, 6, 'multi', 'وُلد السيد أبو القاسم الخوئي عام 1899م في مدينة خوي الإيرانية، ثم انتقل إلى النجف الأشرف حيث درس وتتلمذ وأصبح لاحقاً زعيماً للحوزة العلمية فيها.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_22, 'ما الموسوعة الروائية الضخمة التي أشرف السيد الخوئي على تأليفها في علم الرجال والتي تُعدّ مرجعاً لا غنى عنه؟', '["الغدير في الكتاب والسنة والأدب","جواهر الكلام","معجم رجال الحديث","مستمسك العروة الوثقى"]'::jsonb, 2, 20, 7, 'multi', 'موسوعة ''معجم رجال الحديث'' للسيد الخوئي تقع في أكثر من عشرين مجلداً، وتُعدّ من أوسع وأدق المعاجم الرجالية في التراث الإمامي.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_22, 'ما الكتاب الفقهي الكبير الذي ألّفه الشيخ الطوسي والذي يُعدّ أحد الكتب الأربعة المعتمدة في الفقه الإمامي؟', '["من لا يحضره الفقيه","الكافي","نهج البلاغة","تهذيب الأحكام"]'::jsonb, 3, 20, 8, 'multi', 'كتاب ''تهذيب الأحكام'' للشيخ الطوسي هو أحد الكتب الأربعة الحديثية الفقهية المعتمدة عند الإمامية، إلى جانب الكافي والاستبصار ومن لا يحضره الفقيه.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_22, 'ما الموقف الفقهي الذي عُرف به السيد الخوئي ويميّزه عن بعض المراجع في مسألة ولاية الفقيه؟', '["أنه أيّد الولاية المطلقة للفقيه في الشؤون السياسية","أنه اقتصر على الولاية في الحسبة ولم يقل بالولاية المطلقة للفقيه","أنه رفض أي شكل من أشكال ولاية الفقيه","أنه قال بولاية الفقيه في الشؤون العسكرية فقط"]'::jsonb, 1, 20, 9, 'multi', 'اشتُهر السيد الخوئي بموقفه الفقهي الذي يقتصر فيه على الولاية في أمور الحسبة والشؤون الحسبية، في مقابل نظرية الولاية المطلقة للفقيه التي قال بها السيد الخميني.', 'تاريخ التشيع والفرق');
END $$;

DO $$
DECLARE
  v_quiz_id_23 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('تاريخ الحوزات العلمية (النجف، قم، كربلاء، البحرين)', 'إسلاميات', 'تاريخ التشيع والفرق', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_23;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_23, 'من هو العالم الذي يُعدّ المؤسس الفعلي للحوزة العلمية في النجف الأشرف في القرن الخامس الهجري؟', '["الشيخ المفيد","الشيخ الطوسي","الكليني","السيد المرتضى"]'::jsonb, 1, 20, 0, 'multi', 'الشيخ محمد بن الحسن الطوسي (ت460هـ) نقل مركز الدراسات الشيعية من بغداد إلى النجف بعد الاضطرابات التي تعرض لها، فأسّس الحوزة العلمية هناك وجعلها مرجعاً علمياً أساسياً للإمامية.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_23, 'في أي قرن هجري تأسست الحوزة العلمية في مدينة قم على يد العلماء المهاجرين من العراق والكوفة؟', '["القرن الرابع الهجري","القرن السادس الهجري","القرن العاشر الهجري","القرن الثاني الهجري"]'::jsonb, 3, 20, 1, 'multi', 'تأسست الحوزة العلمية في قم في القرن الثاني الهجري، إذ هاجر إليها الأشعريون من الكوفة وعلى رأسهم موسى بن عبدالله الأشعري، وغدت مركزاً للتشيع الإمامي مبكراً جداً.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_23, 'من هو العالم الإيراني الذي أحيا الحوزة العلمية في قم في القرن الرابع عشر الهجري وجعلها مرجعية علمية بارزة؟', '["الشيخ عبدالكريم الحائري اليزدي","السيد أبو الحسن الأصفهاني","الشيخ محمد حسين الغروي الأصفهاني","الميرزا النائيني"]'::jsonb, 0, 20, 2, 'multi', 'الشيخ عبدالكريم الحائري اليزدي (ت1355هـ) هو من أعاد تأسيس الحوزة العلمية في قم عام 1340هـ وأرسى قواعدها الحديثة، فأصبحت لاحقاً منافسة للنجف في المرجعية العلمية.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_23, 'ما هو الاسم الذي اشتُهرت به الحوزة العلمية في النجف تاريخياً وهو يدل على مكانتها الرفيعة؟', '["عتبة النجف","المشهد الغروي","دار العلم","الحضرة العلوية"]'::jsonb, 2, 20, 3, 'multi', 'اشتُهرت الحوزة العلمية في النجف تاريخياً بـ''دار العلم'' نسبةً إلى المدرسة التي أسسها الشيخ الطوسي، كما وصفها المؤرخون بأنها قبلة العلماء والطلاب الشيعة على مدار قرون.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_23, 'أيّ أسرة حاكمة إيرانية كان لها الفضل الأكبر في دعم الحوزات العلمية الشيعية وتحويل إيران رسمياً إلى التشيع الاثني عشري؟', '["البويهيون","الصفويون","السلجوقيون","الغزنويون"]'::jsonb, 1, 20, 4, 'multi', 'الدولة الصفوية (906-1135هـ) هي التي أعلنت التشيع الاثني عشري مذهباً رسمياً لإيران، واستقدمت العلماء من جبل عامل والعراق والبحرين لتعزيز الحوزات وتأهيل الكوادر العلمية.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_23, 'بأي اسم اشتُهرت كربلاء علمياً في الفترة الممتدة بين القرنين الثاني عشر والثالث عشر الهجري إذ ازدهرت فيها حركة علمية بارزة؟', '["حوزة كربلاء الكبرى","حوزة الطفوف","حوزة الفرات الأوسط","مدرسة الكاظمية"]'::jsonb, 0, 20, 5, 'multi', 'في القرنين الثاني عشر والثالث عشر الهجري ازدهرت ''حوزة كربلاء الكبرى'' وبلغت أوجها على يد علماء من أمثال الوحيد البهبهاني الذي أسّس فيها مدرسة فكرية مناهضة للأخباريين وأحيا المنهج الأصولي.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_23, 'من هو العالم الذي يُنسب إليه إحياء المنهج الأصولي في حوزة كربلاء في القرن الثاني عشر الهجري ويُلقّب بـ''أستاذ الكل''؟', '["السيد مهدي بحر العلوم","الشيخ جعفر كاشف الغطاء","الوحيد البهبهاني","الشيخ يوسف البحراني"]'::jsonb, 2, 20, 6, 'multi', 'الوحيد البهبهاني (ت1205هـ) هو محمد باقر البهبهاني الذي أحيا المنهج الأصولي في كربلاء ورد على الأخباريين، ولُقِّب بـ''أستاذ الكل'' لكثرة تلاميذه الذين صاروا مراجع كبار.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_23, 'من أبرز العلماء الذين هاجروا من البحرين إلى إيران في العصر الصفوي ولعبوا دوراً محورياً في تطوير الحوزات العلمية الإيرانية؟', '["ابن قولويه","الشيخ البهائي","الشيخ الصدوق","الشيخ المفيد"]'::jsonb, 1, 20, 7, 'multi', 'الشيخ البهائي (ت1030هـ) بهاء الدين العاملي البحراني الأصل هاجر إلى إيران وتولى شيخ الإسلام في أصفهان، وأسهم في بناء الحوزات العلمية الصفوية وصياغة المناهج الدراسية فيها.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_23, 'ما الحدث التاريخي الذي أدى إلى انتقال مركز المرجعية الشيعية من بغداد إلى النجف في منتصف القرن الخامس الهجري؟', '["غزو الحمدانيين لبغداد","انهيار الدولة البويهية على يد السلاجقة","اجتياح المغول لبغداد","الفتنة الطائفية في بغداد وإحراق دار الشيخ الطوسي"]'::jsonb, 3, 20, 8, 'multi', 'في عام 448هـ تعرّض الشيخ الطوسي للاضطهاد في بغداد وأُحرقت داره ومكتبته بسبب الفتنة الطائفية في عهد السلاجقة، فاضطر إلى الهجرة إلى النجف حيث أسّس حوزتها العلمية.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_23, 'أيّ المدارس الدينية في البحرين يُعدّ من أقدم مراكز الدراسة الشيعية في الجزيرة العربية ويرتبط بآل العصفور وشيوخ البحرين؟', '["المدرسة العصفورية","المدرسة القاسمية","مدرسة ابن أبي جمهور","مدرسة الشيخ الماحوزي"]'::jsonb, 0, 20, 9, 'multi', 'المدرسة العصفورية ترتبط بالشيخ يوسف البحراني صاحب ''الحدائق الناضرة'' (ت1186هـ) وبآل العصفور، وهي من أبرز مراكز الدراسة الشيعية في البحرين التي أنجبت علماء كثيرين وحافظت على التراث الأخباري.', 'تاريخ التشيع والفرق');
END $$;

DO $$
DECLARE
  v_quiz_id_24 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('المرجعية الدينية ومفهوم التقليد والاجتهاد', 'إسلاميات', 'تاريخ التشيع والفرق', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_24;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_24, 'ما المقصود بمصطلح ''التقليد'' في الفقه الجعفري؟', '["الالتزام بآراء الصحابة في المسائل الدينية","اتباع المجتهد الحي الأعلم في الأحكام الشرعية الفرعية","حفظ الأحاديث النبوية وروايتها","تقليد المذاهب الفقهية السنية الأربعة"]'::jsonb, 1, 20, 0, 'multi', 'التقليد في الفقه الجعفري يعني رجوع غير المجتهد إلى المجتهد الحي الأعلم في استنباط الأحكام الشرعية الفرعية العملية، وهو واجب على كل مكلف غير قادر على الاجتهاد.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_24, 'ما الشرط الأساسي الذي اشترطه الفقهاء الإماميون في مرجع التقليد حتى يصح الرجوع إليه؟', '["أن يكون من النسب الهاشمي","أن يكون قد درس في الحوزة العلمية أربعين سنة","الأعلمية في استنباط الأحكام الشرعية","الإقامة في مدينة النجف الأشرف"]'::jsonb, 2, 20, 1, 'multi', 'يشترط جمهور الفقهاء الإماميين في مرجع التقليد أن يكون أعلم المجتهدين المتوفرين، أي الأقدر على استنباط الأحكام الشرعية من أدلتها التفصيلية.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_24, 'من هو الفقيه الإمامي الذي يُعدّ من أبرز المؤسسين لمنهج الاجتهاد الفقهي المنظم في الحوزة العلمية في القرن الرابع الهجري؟', '["الكليني","الشيخ الطوسي","ابن أبي عقيل العماني","الشيخ المفيد"]'::jsonb, 3, 20, 2, 'multi', 'الشيخ المفيد (ت 413هـ) يُعدّ من أبرز من أسّس لمنهج الاجتهاد العقلي المنضبط في الفقه الإمامي، إذ دمج الروايات بالعقل في استنباط الأحكام ووضع قواعد منهجية للفقه الجعفري.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_24, 'ما الفرق الجوهري بين ''الإخباريين'' و''الأصوليين'' في التراث الشيعي الإمامي؟', '["الإخباريون يكتفون بالروايات المأثورة وينكرون الاجتهاد بينما الأصوليون يُجيزون استخدام الأدلة العقلية والأصول الفقهية","الإخباريون يُقدّمون العقل على النقل بينما الأصوليون يُقدّمون النقل","الإخباريون يتبعون المذهب السني بينما الأصوليون يتبعون المذهب الجعفري","الإخباريون يُجيزون الاجتهاد بالرأي بينما الأصوليون يرفضونه"]'::jsonb, 0, 20, 3, 'multi', 'الإخباريون كالمحدث الاسترابادي (ت 1036هـ) يرون الاكتفاء بروايات أهل البيت ورفض الاجتهاد والأصول العقلية، بينما الأصوليون يُجيزون استخدام علم الأصول والعقل في استنباط الأحكام.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_24, 'من الفقيه الإمامي الذي أسّس نظرية ''ولاية الفقيه'' بمفهومها السياسي الشامل في العصر الحديث؟', '["السيد محسن الحكيم","السيد الخوئي","الإمام الخميني","الشيخ مرتضى الأنصاري"]'::jsonb, 2, 20, 4, 'multi', 'الإمام روح الله الخميني (ت 1989م) هو من طوّر نظرية ''ولاية الفقيه المطلقة'' وأعطاها بُعداً سياسياً شاملاً في كتابه ''الحكومة الإسلامية''، وطبّقها عملياً في إيران عام 1979م.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_24, 'في أي عصر ظهرت مرجعية دينية مركزية واحدة للشيعة الإمامية تُعرف بـ''المرجعية العليا''؟', '["في عصر الأئمة المعصومين","في القرن الثاني الهجري","منذ الفتح الإسلامي","ابتداءً من القرن الثالث عشر الهجري مع تطور الحوزات العلمية"]'::jsonb, 3, 20, 5, 'multi', 'تبلورت فكرة المرجعية الدينية المركزية الشاملة تدريجياً في القرن الثالث عشر الهجري مع الشيخ مرتضى الأنصاري الذي يُعدّ أول من تمركزت فيه المرجعية العليا بشكل واسع في الحوزة النجفية.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_24, 'ما موقف الشيخ الطوسي (ت 460هـ) من مسألة الاجتهاد في الفقه الإمامي؟', '["تبنّى الاجتهاد القياسي على غرار الفقه السني","أسّس منهجاً اجتهادياً رصيناً جمع فيه بين الروايات وعلم الأصول وأرسى قواعد الفقه الإمامي","رفض الاجتهاد كلياً وأوجب الاقتصار على الروايات","أوجب على العامة الاجتهاد المباشر بأنفسهم"]'::jsonb, 1, 20, 6, 'multi', 'الشيخ الطوسي المعروف بـ''شيخ الطائفة'' أرسى منهجاً اجتهادياً متكاملاً في كتابيه ''المبسوط'' و''الخلاف''، ووضع قواعد راسخة للفقه الإمامي جمع فيها الروايات والعقل والأصول.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_24, 'كيف يُعرَّف ''الاجتهاد'' في المصطلح الفقهي الإمامي؟', '["هو بذل الجهد للوصول إلى الحكم الشرعي الظني من أدلته التفصيلية","هو القدرة على حفظ القرآن الكريم كاملاً","هو الاطلاع الواسع على تاريخ الإسلام","هو إصدار الفتاوى في المسائل السياسية فحسب"]'::jsonb, 0, 20, 7, 'multi', 'الاجتهاد في الاصطلاح الفقهي الإمامي هو استفراغ الوسع وبذل الجهد للوصول إلى الحكم الشرعي الفرعي الظني من أدلته التفصيلية كالكتاب والسنة والعقل والإجماع.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_24, 'ما الفرقة الشيعية التي رفضت مبدأ الاجتهاد ومرجعية الفقهاء وجعلت الإمامة حكراً على النسل المباشر للأئمة الاثني عشر؟', '["الإسماعيلية","الزيدية","النصيرية","الإخبارية المتشددة"]'::jsonb, 3, 20, 8, 'multi', 'المحدث الإخباري المتشدد محمد أمين الاسترابادي وأتباعه رفضوا مرجعية الفقهاء المجتهدين في غيبة الإمام وأوجبوا الاقتصار على الروايات المأثورة دون تدخل العقل والاجتهاد.', 'تاريخ التشيع والفرق');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_24, 'ما الدور الذي أدّاه السيد بحر العلوم (ت 1212هـ) في تطور المرجعية الدينية الشيعية؟', '["أسّس مذهب الإخبارية في القرن الثاني عشر","كان من أوائل من تمتعوا بمرجعية دينية واسعة النطاق في الحوزة النجفية مما مهّد لتقنين مؤسسة المرجعية","ألّف أول كتاب في أصول الفقه الإمامي","أسّس الحوزة العلمية في قم"]'::jsonb, 1, 20, 9, 'multi', 'السيد مهدي بحر العلوم يُعدّ من الشخصيات البارزة التي رسّخت مفهوم المرجعية الدينية في الحوزة النجفية، وتتلمذ عليه كبار الفقهاء اللاحقين مما ساهم في تطور مؤسسة المرجعية وبلورتها.', 'تاريخ التشيع والفرق');
END $$;

DO $$
DECLARE
  v_quiz_id_25 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('تاريخ المآتم والحسينيات في البحرين وأشهرها', 'إسلاميات', 'المآتم والشعائر المحلية (البحرين)', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_25;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_25, 'ما هو المصطلح المحلي البحريني الذي يُطلق على المكان المخصص لإقامة الشعائر الحسينية وإحياء ذكرى استشهاد الإمام الحسين؟', '["المأتم","المجلس","الحسينية","الديوانية"]'::jsonb, 0, 20, 0, 'multi', 'يُعرف المكان المخصص لإحياء الشعائر الحسينية في البحرين بـ''المأتم''، وهو مصطلح خاص بالبحرين يختلف عن مصطلح ''الحسينية'' المستخدم في إيران والعراق، وإن كان المعنى متقارباً.', 'المآتم والشعائر المحلية (البحرين)');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_25, 'يُعدّ مأتم العوامية في البحرين من أعرق المآتم، فإلى أي منطقة ينتسب؟', '["القطيف","سترة","المحرق","المنامة"]'::jsonb, 2, 20, 1, 'multi', 'مأتم العوامية ينتسب إلى منطقة المحرق في البحرين، وهو من المآتم العريقة التي تمتد جذورها لعدة قرون وتقام فيه الشعائر الحسينية بصورة منتظمة.', 'المآتم والشعائر المحلية (البحرين)');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_25, 'ما الوظيفة الأساسية التي يؤديها المأتم في المجتمع البحريني الشيعي إضافة إلى إحياء الشعائر الحسينية؟', '["مركز تجاري","مقر حكومي","مدرسة دينية حصراً","مركز اجتماعي وديني متعدد الأغراض"]'::jsonb, 3, 20, 2, 'multi', 'يؤدي المأتم في البحرين دور المركز الاجتماعي والديني متعدد الأغراض، إذ يُستخدم لإقامة مجالس العزاء والأفراح والتجمعات القبلية وحل النزاعات، فضلاً عن إحياء المناسبات الدينية.', 'المآتم والشعائر المحلية (البحرين)');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_25, 'ما المأتم الذي يُعدّ من أقدم وأشهر مآتم منطقة الدراز في البحرين ويرتبط بعائلة عريقة؟', '["مأتم آل عصفور","مأتم السادة","مأتم آل خليفة","مأتم آل سيادي"]'::jsonb, 0, 20, 3, 'multi', 'يُعدّ مأتم آل عصفور من أبرز وأقدم مآتم منطقة الدراز في البحرين، وينتسب إلى عائلة آل عصفور ذات الحضور الديني والاجتماعي البارز في تاريخ البحرين.', 'المآتم والشعائر المحلية (البحرين)');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_25, 'تتميز شعائر العشرة الأولى من محرم في البحرين بممارسة خاصة تُعرف بـ''اللطم''، فما المقصود بها في السياق البحريني؟', '["قراءة القرآن الكريم جماعياً","ضرب الصدر تعبيراً عن الحزن والرثاء","إقامة موائد الطعام للفقراء","المسير الجماعي بالمشاعل"]'::jsonb, 1, 20, 4, 'multi', 'اللطم هو ضرب الصدر إيقاعياً بالأيدي تعبيراً عن الحزن والحداد على استشهاد الإمام الحسين وأصحابه، وهو من أبرز الشعائر الجماعية التي تُقام في مآتم البحرين خلال العشرة الأولى من محرم.', 'المآتم والشعائر المحلية (البحرين)');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_25, 'ما المنطقة البحرينية التي تضم أكبر تجمع للمآتم الشيعية وتُعدّ مركزاً للشعائر الحسينية في المنامة؟', '["منطقة سار","منطقة عراد","منطقة الشاخورة والزنج","منطقة الرفاع"]'::jsonb, 2, 20, 5, 'multi', 'تضم منطقتا الشاخورة والزنج في المنامة تجمعاً كبيراً من المآتم الشيعية، وتُعدّان من أبرز المناطق التي تشهد إحياءات حسينية واسعة النطاق طوال موسم العزاء.', 'المآتم والشعائر المحلية (البحرين)');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_25, 'ما الشخصية الدينية البحرينية التي ارتبط اسمها تاريخياً بتنظيم الشعائر الحسينية وتأسيس المجالس العلمية في مآتم البحرين خلال القرن الثاني عشر الهجري؟', '["الشيخ ميثم البحراني","السيد هاشم البحراني","الشيخ علي البلادي","الشيخ يوسف البحراني"]'::jsonb, 3, 20, 6, 'multi', 'الشيخ يوسف البحراني صاحب كتاب ''الحدائق الناضرة'' هو من أبرز علماء البحرين في القرن الثاني عشر الهجري، وقد أسهم في تنظيم الشعائر الدينية والمجالس العلمية وإحياء الموروث الحسيني في البحرين.', 'المآتم والشعائر المحلية (البحرين)');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_25, 'يُقام موكب ''زيارة الأربعين'' في البحرين سنوياً، فما الحدث الذي يُحيي هذا الموكب ذكراه؟', '["ذكرى غيبة الإمام الثاني عشر","الذكرى الأربعينية لاستشهاد الإمام الحسين في كربلاء","ذكرى واقعة الجمل","ذكرى ولادة الإمام الحسين"]'::jsonb, 1, 20, 7, 'multi', 'يُحيي موكب زيارة الأربعين الذكرى الأربعينية لاستشهاد الإمام الحسين بن علي في كربلاء، ويُصادف العشرين من صفر من كل عام، ويُعدّ من أبرز الشعائر التي تشارك فيها مآتم البحرين.', 'المآتم والشعائر المحلية (البحرين)');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_25, 'ما المصطلح الذي يُطلقه أهل البحرين على الخطيب أو القارئ الذي يتولى إلقاء المراثي وقراءة سيرة أهل البيت في مجالس المآتم؟', '["المنشد","المقرئ","الخطيب أو القارئ الحسيني","الرادود"]'::jsonb, 2, 20, 8, 'multi', 'يُعرف من يتولى إلقاء الخطب والمراثي وقراءة سيرة أهل البيت في مجالس المآتم البحرينية بـ''الخطيب'' أو ''القارئ الحسيني''، وللخطباء مكانة رفيعة في المجتمع الشيعي البحريني.', 'المآتم والشعائر المحلية (البحرين)');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_25, 'أيّ من المآتم التالية يُعدّ من أشهر المآتم في منطقة النعيم بالمنامة ويتميز بإقامة مواكب حسينية كبرى؟', '["مأتم بن رجب","مأتم آل فرج الله","مأتم آل رمضان","مأتم آل غريب"]'::jsonb, 0, 20, 9, 'multi', 'يُعدّ مأتم بن رجب من أبرز وأشهر المآتم في منطقة النعيم بالمنامة، وله تاريخ عريق في إقامة الشعائر الحسينية والمواكب الكبرى خلال موسم محرم وصفر.', 'المآتم والشعائر المحلية (البحرين)');
END $$;

DO $$
DECLARE
  v_quiz_id_26 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('علماء ومراجع بحرينيين معروفين تاريخياً', 'إسلاميات', 'علماء البحرين', 'standard', 'ar', true)
  RETURNING id INTO v_quiz_id_26;

  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_26, 'من هو العالم البحريني الشهير صاحب كتاب ''الحدائق الناضرة في أحكام العترة الطاهرة''؟', '["الشيخ ميثم البحراني","الشيخ سليمان الماحوزي","الشيخ علي بن سليمان البحراني","الشيخ يوسف البحراني"]'::jsonb, 3, 20, 0, 'multi', 'الشيخ يوسف البحراني المتوفى سنة 1186هـ هو صاحب موسوعة ''الحدائق الناضرة'' الفقهية الكبرى، وهو من أبرز علماء الإمامية في القرن الثاني عشر الهجري.', 'علماء البحرين');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_26, 'من هو العالم البحراني الفيلسوف والمتكلم صاحب كتاب ''قواعد المرام في علم الكلام''؟', '["الشيخ أحمد بن صالح البحراني","الشيخ سليمان الماحوزي","الشيخ ميثم بن علي البحراني","الشيخ يوسف البحراني"]'::jsonb, 2, 20, 1, 'multi', 'الشيخ ميثم بن علي البحراني المتوفى سنة 679هـ عالم جليل في الفلسفة والكلام، وله أيضاً شرح شهير على نهج البلاغة.', 'علماء البحرين');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_26, 'ما اسم العالم البحراني الذي لُقِّب بـ''شيخ البحرين'' وكان من أبرز علمائها في القرن الحادي عشر الهجري، وصاحب كتاب ''معراج أهل الكمال''؟', '["الشيخ أحمد بن محمد البلادي","الشيخ سليمان بن عبدالله الماحوزي","الشيخ علي بن سليمان القدمي","الشيخ حسين بن شهاب الدين العاملي"]'::jsonb, 1, 20, 2, 'multi', 'الشيخ سليمان الماحوزي المتوفى سنة 1121هـ من أبرز علماء البحرين وفقهائها، وقد ترك آثاراً علمية جليلة في الفقه والرجال.', 'علماء البحرين');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_26, 'من هو العالم البحراني صاحب كتاب ''أنوار البدرين في تراجم علماء القطيف والأحساء والبحرين''؟', '["الشيخ عبدالله بن صالح السماهيجي","الشيخ ميثم البحراني","الشيخ يوسف البحراني","الشيخ علي بن حسن البلادي البحراني"]'::jsonb, 3, 20, 3, 'multi', 'الشيخ علي بن حسن البلادي البحراني المتوفى سنة 1340هـ هو مؤلف كتاب ''أنوار البدرين''، وهو مرجع تراجمي مهم لعلماء المنطقة.', 'علماء البحرين');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_26, 'من هو العالم البحراني الذي كان من أبرز تلامذة العلامة الحلي وأسهم في نشر الفقه الإمامي، وهو صاحب كتاب ''إشارة السبق''؟', '["الشيخ علي بن سليمان البحراني القدمي","الشيخ يوسف البحراني","الشيخ ميثم البحراني","الشيخ إبراهيم الكفعمي"]'::jsonb, 0, 20, 4, 'multi', 'الشيخ علي بن سليمان البحراني القدمي من علماء القرن الثامن الهجري وتلميذ العلامة الحلي، وكتابه ''إشارة السبق'' في الفقه الإمامي.', 'علماء البحرين');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_26, 'من هو العالم البحراني الشهير بالأخبارية ومؤلف ''لؤلؤة البحرين'' في تراجم العلماء؟', '["الشيخ سليمان الماحوزي","الشيخ عبدالله السماهيجي","الشيخ يوسف البحراني","الشيخ ميثم البحراني"]'::jsonb, 2, 20, 5, 'multi', 'الشيخ يوسف البحراني هو مؤلف كتاب ''لؤلؤة البحرين'' أيضاً إلى جانب ''الحدائق الناضرة''، وقد كان يميل في بداياته للأخبارية ثم اتخذ موقفاً وسطياً.', 'علماء البحرين');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_26, 'من هو العالم البحراني الذي كتب شرحاً موسعاً على نهج البلاغة في خمسة مجلدات ويُعدّ من أشهر شروحه؟', '["الشيخ سليمان الماحوزي","الشيخ ميثم بن علي البحراني","الشيخ عبدالله السماهيجي","الشيخ يوسف البحراني"]'::jsonb, 1, 20, 6, 'multi', 'الشيخ ميثم البحراني المتوفى سنة 679هـ صنّف شرحاً كبيراً على نهج البلاغة في خمسة مجلدات يُعدّ من أمهات شروحه حتى اليوم.', 'علماء البحرين');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_26, 'من هو العالم البحراني المتوفى سنة 1135هـ الذي تميّز بعلم الرجال والحديث وكتب ''منية الممارسين''؟', '["الشيخ سليمان الماحوزي","الشيخ علي البلادي","الشيخ يوسف البحراني","الشيخ عبدالله بن صالح السماهيجي"]'::jsonb, 3, 20, 7, 'multi', 'الشيخ عبدالله بن صالح السماهيجي المتوفى سنة 1135هـ من كبار علماء البحرين، وله مؤلفات في الرجال والفقه والحديث.', 'علماء البحرين');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_26, 'ما النسبة التي اشتُهر بها الشيخ يوسف البحراني في كتبه ومؤلفاته؟', '["الماحوزي","الستراوي","الدرازي","السماهيجي"]'::jsonb, 2, 20, 8, 'multi', 'الشيخ يوسف البحراني ينتسب إلى قرية ''دراز'' في البحرين، ولهذا يُعرف بـ''الدرازي'' نسبةً إليها، وهو ما يُذكر في مؤلفاته.', 'علماء البحرين');
  INSERT INTO questions (quiz_id, question_text, options, correct_index, time_limit_seconds, order_index, question_type, explanation, subcategory)
  VALUES (v_quiz_id_26, 'من هو العالم البحراني الذي جمع بين الفقه والأدب والشعر، وكان من شيوخ إجازة الحديث في البحرين في القرن الثاني عشر الهجري، ويُكنّى بـ''أبي علي''؟', '["الشيخ أحمد بن صالح البحراني المعروف بابن طعان","الشيخ ميثم البحراني","الشيخ سليمان الماحوزي","الشيخ علي البلادي"]'::jsonb, 0, 20, 9, 'multi', 'الشيخ أحمد بن صالح البحراني المعروف بابن طعان من علماء البحرين البارزين الذين جمعوا بين الفقه والأدب وإجازة الحديث.', 'علماء البحرين');
END $$;

DO $$
DECLARE
  v_quiz_id_27 uuid;
BEGIN
  INSERT INTO quizzes (title, category, subcategory, quiz_difficulty, language, is_public)
  VALUES ('طقوس عاشوراء بالطابع الخليجي والبحريني', 'إسلاميات', 'المناسبات الخليجية الدينية', 'standard', 'ar', true)
